async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0, x = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  g.PRSI = i;
  g.PRSO = o;
  if ((g.LIT == 0) && (await SEE_VERB$())) {
    await TOO_DARK();
    return M_FATAL;
  } else if (!(isVerb(V.WALK))) {
    if (IT == g.PRSI || IT == g.PRSO) {
      if (!(await FIX_HIM_HER_IT(IT, g.P_IT_OBJECT))) {
        return M_FATAL;
      }
    }
    if (HER == g.PRSI || HER == g.PRSO) {
      if (!(await FIX_HIM_HER_IT(HER, g.P_HER_OBJECT))) {
        return M_FATAL;
      }
    }
    if (HIM == g.PRSI || HIM == g.PRSO) {
      if (!(await FIX_HIM_HER_IT(HIM, g.P_HIM_OBJECT))) {
        return M_FATAL;
      }
    }
  }
  v_ = false;
  if (!(a_ == V.WALK) && (NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI)) {
    (v_ = (await D_APPLY("Not Here", NOT_HERE_OBJECT_F.id)));
    if (v_) {
      g.P_WON = false;
    }
  }
  await THIS_IS_IT(g.PRSI);
  await THIS_IS_IT(g.PRSO);
  if (!(g.WINNER == PLAYER)) {
    await THIS_IS_IT(g.WINNER);
  }
  o = g.PRSO;
  i = g.PRSI;
  if (v_ == 0) {
    (v_ = (await D_APPLY("Actor", getProp(g.WINNER, P.ACTION), M_WINNER)));
  }
  if (v_ == 0) {
    (v_ = (await D_APPLY("Room (M-BEG)", getProp(loc(g.WINNER) == CAR ? CAR : g.HERE, P.ACTION), M_BEG)));
  }
  if (v_ == 0) {
    (v_ = (await D_APPLY("Preaction", get(g.PREACTIONS, a_))));
  }
  g.NOW_PRSI = 1;
  if ((v_ == 0) && i) {
    (v_ = (await D_APPLY("PRSI", getProp(i, P.ACTION))));
  }
  g.NOW_PRSI = 0;
  if ((v_ == 0) && o && !(a_ == V.WALK)) {
    (v_ = (await D_APPLY("PRSO", getProp(o, P.ACTION))));
  }
  if (v_ == 0) {
    v_ = await D_APPLY(false, get(g.ACTIONS, a_));
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

