async function GENERIC_BEDROOM(tbl, n_ = 0) {
  let rm = 0;
  if (n_ == 0) {
    n_ = getb(tbl, P_MATCHLEN);
  }
  if (rm = await ZMEMQ(g.HERE, g.CHAR_CLOSET_TABLE)) {
    if (W.DOOR == g.P_NAM || W.DOOR == g.P_XNAM) {
      return await FIND_FLAG_LG(g.HERE, DOORBIT);
    } else {
      return get(g.CHAR_ROOM_TABLE, rm);
    }
  } else if ((A.JACK_S == g.P_ADJ || A.JACK_S == g.P_XADJ) && (W.DOOR == g.P_NAM || W.DOOR == g.P_XNAM)) {
    return JACK_ROOM;
  } else if (await ZMEMQB(g.P_IT_OBJECT, tbl)) {
    return g.P_IT_OBJECT;
  } else if (await ZMEMQB(g.HERE, tbl)) {
    return g.HERE;
  } else if (await REMOTE_VERB$()) {
    if (A.BATH == g.P_ADJ || A.BATH == g.P_XADJ) {
      return YOUR_BATHROOM;
    } else if (W.ROOM == g.P_NAM || W.ROOM == g.P_XNAM) {
      return YOUR_ROOM;
    } else {
      rm = false;
    }
  } else if (g.HERE == GALLERY || g.HERE == YOUR_BATHROOM) {
    return YOUR_ROOM;
  } else if (await ZMEMQ(g.HERE, g.CHAR_ROOM_TABLE)) {
    return g.HERE;
  } else if (isVerb(V.CLIMB_DOWN, V.CLIMB_UP, V.WALK_TO)) {
    return YOUR_ROOM;
  } else {
    loop1: for (;;) {
      if (g.HERE == getProp(rm = getb(tbl, n_), P.STATION)) {
        break loop1;
      } else if (--n_ < 1) {
        rm = false;
        break loop1;
      }
    }
  }
  if (!(rm == 0)) {
    return rm;
  } else if (g.WINNER == FRIEND || g.WINNER == LORD) {
    return YOUR_ROOM;
  } else {
    return false;
  }
}

