async function WHICH_PRINT(tlen, len, tbl) {
  let obj = 0, rlen = 0;
  if (len == 0) {
    await MORE_SPECIFIC();
    return false;
  }
  rlen = len;
  if (!(g.WINNER == PLAYER)) {
    tell("\"I don't understand ");
    if (g.P_NAM == W.DOOR) {
      tell("which door");
    } else {
      tell("if");
    }
    tell(" you mean");
  } else {
    tell("[Which");
    if (!(g.P_OFLAG == 0) || !(g.P_MERGED == 0) || !(g.P_AND == 0)) {
      if (!(g.P_NAM == 0)) {
        tell(C(32));
        printB(g.P_NAM);
      }
    } else if (tbl == g.P_PRSO) {
      await CLAUSE_PRINT(P_NC1, P_NC1L, false);
    } else {
      await CLAUSE_PRINT(P_NC2, P_NC2L, false);
    }
    tell(" do you mean");
    if (!(g.P_NAM == W.DOOR)) {
      tell(",");
    }
  }
  if (!(g.P_NAM == W.DOOR)) {
    loop1: for (;;) {
      tlen = tlen + 1;
      obj = getb(tbl, tlen);
      await PRINTT(obj);
      if (len == 2) {
        if (!(rlen == 2)) {
          tell(C(44));
        }
        tell(" or");
      } else if (len > 2) {
        tell(C(44));
      }
      if ((len = len - 1) < 1) {
        break loop1;
      }
    }
  }
  if (!(g.WINNER == PLAYER)) {
    tell(".\"\n");
    return true;
  } else {
    tell("?]\n");
    return true;
  }
}

async function GLOBAL_SEARCH(tbl, rmg) {
  let cnt = 0, obj = 0;
  cnt = propSize(rmg) - 1;
  for (;;) {
    obj = getb(rmg, cnt);
    if (await THIS_IT$(obj)) {
      await OBJ_FOUND(obj, tbl);
    }
    if (--cnt < 0) {
      return true;
    }
  }
}

async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obits = 0, foo = 0;
  len = getb(tbl, P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    await GLOBAL_SEARCH(tbl, rmg);
  }
  if (!(g.P_NAM == W.DOOR)) {
    if ((await THIS_IT$(g.HERE)) && !(await ZMEMQB(g.HERE, tbl))) {
      await OBJ_FOUND(g.HERE, tbl);
    }
    if (isVerb(V.BOARD, V.CLIMB_DOWN, V.CLIMB_UP, V.EXAMINE, V.LOOK_INSIDE, V.THROUGH)) {
      await ROOM_SEARCH(tbl);
    }
  }
  if (rmg = getProp(g.HERE, P.THINGS)) {
    rmgl = get(rmg, 0);
    cnt = 0;
    loop1: for (;;) {
      if ((g.P_NAM == get(rmg, cnt + 1)) && ((g.P_ADJ == 0) || (g.P_ADJN == get(rmg, cnt + 2)))) {
        g.LAST_PSEUDO_LOC = g.HERE;
        putProp(PSEUDO_OBJECT, P.ACTION, get(rmg, cnt + 3));
        foo = getPropAddr(PSEUDO_OBJECT, P.ACTION) - 5;
        put(foo, 0, get(g.P_NAM, 0));
        put(foo, 1, get(g.P_NAM, 1));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop1;
      }
      cnt = cnt + 3;
      if (!(cnt < rmgl)) {
        break loop1;
      }
    }
  }
  if (eq(getb(tbl, P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    g.P_SLOCBITS = obits;
    if (getb(tbl, P_MATCHLEN) == 0) {
      if (isVerb(V.CLIMB_DOWN, V.CLIMB_UP, V.FIND, V.SHOW, V.SSHOW, V.TAKE_TO, V.THROUGH, V.WALK_TO)) {
        return await SEARCH_LIST(ROOMS, g.P_TABLE, P_SRCTOP);
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bits = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && (await THIS_IT$(obj))) {
        await OBJ_FOUND(obj, tbl);
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && first(obj) && (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT) || g.P_MOBY_FLAG || (hasFlag(obj, PERSONBIT) && !(obj == g.WINNER)))) {
        await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP));
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function ROOM_SEARCH(ttbl) {
  let p_ = 0, l = 0, tbl = 0, o = 0;
  o = await CORRIDOR_LOOK(ROOMS);
  if (!(o == 0)) {
    await OBJ_FOUND(o, ttbl);
  }
  loop1: for (;;) {
    if (((p_ = nextProp(g.HERE, p_)) == 0) || (p_ < LOW_DIRECTION)) {
      return false;
    }
    tbl = getPropAddr(g.HERE, p_);
    l = propSize(tbl);
    o = getb(tbl, REXIT);
    if (await ZMEMQB(o, ttbl)) {
      continue loop1;
    } else if (l == UEXIT) {
      if (await THIS_IT$(o)) {
        await OBJ_FOUND(o, ttbl);
      }
    } else if (l == DEXIT) {
      if (hasFlag(getb(tbl, DEXITOBJ), OPENBIT) && (await THIS_IT$(o))) {
        await OBJ_FOUND(o, ttbl);
      }
    } else if (l == CEXIT) {
      if (globalValue(getb(tbl, CEXITFLAG)) && (await THIS_IT$(o))) {
        await OBJ_FOUND(o, ttbl);
      }
    }
  }
}

async function THIS_IT$(obj) {
  let syns = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (!(g.P_NAM == 0) && (!(syns = getPropAddr(obj, P.SYNONYM)) || !(await ZMEMQ(g.P_NAM, syns, div(propSize(syns), 2) - 1)))) {
    return false;
  } else if (!(g.P_ADJ == 0) && (!(syns = getPropAddr(obj, P.ADJECTIVE)) || !(await ZMEMQB(g.P_ADJ, syns, propSize(syns) - 1)))) {
    return false;
  } else if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  }
  return true;
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  if (!(obj == NOT_HERE_OBJECT) && (await ZMEMQB(obj, tbl))) {
    return false;
  }
  ptr = getb(tbl, P_MATCHLEN);
  ++ptr;
  putb(tbl, ptr, obj);
  return putb(tbl, P_MATCHLEN, ptr);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, bits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = getb(tbl, P_MATCHLEN)) && (btst(bits, SHAVE) || btst(bits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      }
      obj = getb(tbl, ptr + 1);
      if (obj == IT) {
        if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        } else {
          obj = g.P_IT_OBJECT;
        }
      } else if (obj == HER) {
        if (!(await ACCESSIBLE$(g.P_HER_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        } else {
          obj = g.P_HER_OBJECT;
        }
      } else if (obj == HIM) {
        if (!(await ACCESSIBLE$(g.P_HIM_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        } else {
          obj = g.P_HIM_OBJECT;
        }
      }
      if (!(await HELD$(obj, g.WINNER)) && !(obj == HANDS || obj == ROOMS)) {
        g.PRSO = obj;
        if (hasFlag(obj, TRYTAKEBIT)) {
          taken = true;
        } else if (!(g.WINNER == PLAYER)) {
          taken = false;
        } else if (btst(bits, STAKE) && eq(await ITAKE(false), true)) {
          taken = false;
        } else {
          taken = true;
        }
        if (taken && btst(bits, SHAVE)) {
          tell(C(40));
          (await HE_SHE_IT(g.WINNER, true, "is"));
          tell("n't holding");
          if (1 < getb(tbl, P_MATCHLEN)) {
            tell(" those things");
          } else if (obj == NOT_HERE_OBJECT) {
            tell(" that");
          } else {
            await PRINTT(obj);
            await THIS_IS_IT(obj);
          }
          tell("!)\n");
          return false;
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((getb(g.P_PRSO, P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((getb(g.P_PRSI, P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell("[You can't use more than one ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct object with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (!(g.P_OFLAG == 0) || !(g.P_MERGED == 0)) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\"!]\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
    if (!(size > 0)) {
      return false;
    }
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      if (cnt == 0) {
        return true;
      } else {
        return cnt;
      }
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = getb(tbl, 0);
    if (!(size > 0)) {
      return false;
    }
  }
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      if (cnt == 0) {
        return true;
      } else {
        return cnt;
      }
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm = false, rmbit = false) {
  let ohere = 0, lit = false, p_ = 0, tbl = 0, l = 0;
  if (rm == 0) {
    rm = g.HERE;
  }
  if (!(rmbit == 0)) {
    if (!(hasFlag(rm, ONBIT))) {
      return false;
    } else {
      return rm;
    }
  }
  if (hasFlag(rm, ONBIT)) {
    lit = rm;
  } else {
    g.P_GWIMBIT = ONBIT;
    ohere = g.HERE;
    g.HERE = rm;
    putb(g.P_MERGE, P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    await SEARCH_LIST(rm, g.P_TABLE, P_SRCALL);
    if (!(getb(g.P_MERGE, P_MATCHLEN) == 0)) {
      lit = getb(g.P_MERGE, 1);
    }
    g.HERE = ohere;
    g.P_GWIMBIT = 0;
  }
  if (!(lit == 0)) {
    return lit;
  } else if ((rm == GALLERY_CORNER) && hasFlag(GALLERY, ONBIT)) {
    return GALLERY;
  } else {
    loop1: for (;;) {
      if ((p_ = nextProp(rm, p_)) == 0) {
        return false;
      } else if (p_ == P.UP || p_ == P.DOWN) {
        continue loop1;
      } else if (!(p_ < LOW_DIRECTION)) {
        tbl = getPropAddr(rm, p_);
        l = propSize(tbl);
        ohere = getb(tbl, REXIT);
        if ((l == UEXIT) && (await LIT$(ohere, true))) {
          return ohere;
        } else if ((l == DEXIT) && hasFlag(getb(tbl, DEXITOBJ), OPENBIT) && (await LIT$(ohere, true))) {
          return ohere;
        } else if ((l == CEXIT) && globalValue(getb(tbl, CEXITFLAG)) && (await LIT$(ohere, true))) {
          return ohere;
        }
      }
    }
  }
}

