async function ROOM_PEEK(rm, safe = false) {
  let x = false, ohere = 0, olit = 0, txt = 0;
  if (rm == g.HERE) {
    await V_LOOK();
    return true;
  } else if (safe || (await SEE_INTO$(rm))) {
    ohere = g.HERE;
    olit = g.LIT;
    g.HERE = rm;
    await MAKE_ALL_PEOPLE(-12);
    g.LIT = await LIT$();
    tell("You peer ");
    if (hasFlag(rm, SURFACEBIT)) {
      tell("at");
    } else {
      tell("into");
    }
    await HIM_HER_IT(rm);
    tell(C(58), "\n");
    if (await DESCRIBE_OBJECTS()) {
      x = true;
    } else if (txt = getProp(rm, P.LDESC)) {
      x = true;
      tell(S(txt), "\n");
    }
    if (x == 0) {
      tell("You can't see anything suspicious.\n");
    }
    g.HERE = ohere;
    g.LIT = olit;
    return true;
  } else {
    return false;
  }
}

async function SEE_INTO$(there, tell$ = true, ignore_door = false) {
  let p_ = 0, l = 0, tbl = 0, o = 0;
  if (await CORRIDOR_LOOK(there)) {
    return true;
  }
  p_ = 0;
  for (;;) {
    if (((p_ = nextProp(g.HERE, p_)) == 0) || (p_ < LOW_DIRECTION)) {
      if (tell$) {
        await TELL_CANT_FIND();
      }
      return false;
    }
    tbl = getPropAddr(g.HERE, p_);
    l = propSize(tbl);
    if (l == UEXIT) {
      if (eq(getb(tbl, REXIT), there)) {
        return true;
      }
    } else if (l == DEXIT) {
      if (eq(getb(tbl, REXIT), there)) {
        if (hasFlag(getb(tbl, DEXITOBJ), OPENBIT)) {
          return true;
        } else if (await WALK_THRU_DOOR$(tbl, getb(tbl, DEXITOBJ), false)) {
          return true;
        } else if (!(ignore_door == 0)) {
          return true;
        } else {
          if (tell$) {
            g.CLOCK_WAIT = true;
            tell("(The door to that room is closed.)\n");
          }
          return false;
        }
      }
    } else if (l == CEXIT) {
      if (eq(getb(tbl, REXIT), there)) {
        if (globalValue(getb(tbl, CEXITFLAG))) {
          return true;
        } else {
          if (tell$) {
            await TELL_CANT_FIND();
          }
          return false;
        }
      }
    }
  }
}

