async function V_WAIT_UNTIL() {
  let n_ = 0;
  if (!((-1) == g.P_NUMBER) && (g.PRSO == INTNUM || g.PRSO == TURN || g.PRSO == ROOMS)) {
    n_ = g.P_NUMBER;
    if (!(g.P_TIME == 0)) {
      if (n_ < 420) {
        n_ = n_ + 720;
      }
    } else {
      if (n_ < 8) {
        n_ = (n_ * 60) + 720;
      } else if (n_ < 13) {
        n_ = n_ * 60;
      } else if (n_ < 24) {
        n_ = (n_ * 60) - 720;
      } else if (n_ > 99) {
        n_ = mod(n_, 100) + (div(n_, 100) * 60);
      }
      if (n_ < 420) {
        n_ = n_ + 720;
      }
      tell(S(g.I_ASSUME), C(32));
      await TIME_PRINT(n_);
      tell("]\n");
    }
    if (n_ > g.PRESENT_TIME) {
      return await V_WAIT(n_ - g.PRESENT_TIME);
    } else {
      g.CLOCK_WAIT = true;
      tell("(It's already past that time!)\n");
      return true;
    }
  } else {
    return (await YOU_CANT("wait until"));
  }
}

