async function WALK_THRU_DOOR$(pt, obj = 0, tell$ = true) {
  let rm = 0;
  if (obj == 0) {
    obj = getb(pt, DEXITOBJ);
  }
  if (hasFlag(obj, OPENBIT)) {
    return true;
  } else if (hasFlag(obj, SECRETBIT) && !(hasFlag(obj, TOUCHBIT))) {
    if (false == tell$ || false == g.VERBOSITY) {
      return false;
    } else if (!(hasFlag(g.HERE, SECRETBIT))) {
      (await YOU_CANT("go"));
      return false;
    } else if (g.LIT == 0) {
      await NOT_FOUND(obj);
      return false;
    } else {
      if (!(isVerb(V.WALK_TO))) {
        await OPEN_DOOR_AND_CLOSE_IT_AGAIN(obj);
      }
      return true;
    }
  } else if (!(hasFlag(obj, LOCKED))) {
    if (!(isVerb(V.WALK_TO))) {
      clearFlag(obj, SECRETBIT);
      setFlag(obj, SEENBIT);
      if (!(false == tell$ || false == g.VERBOSITY)) {
        await OPEN_DOOR_AND_CLOSE_IT_AGAIN(obj);
      }
    }
    return true;
  } else if (!(pt == 0) && (rm = get(pt, DEXITSTR))) {
    if (!(tell$ == 0)) {
      tell(S(rm), "\n");
    }
    return false;
  } else {
    if (tell$ == 0) {
      return false;
    } else if (!((await UNLOCK_DOOR$(obj)) == 0)) {
      if (!(isVerb(V.WALK_TO)) && !(g.VERBOSITY == 0)) {
        await OPEN_DOOR_AND_CLOSE_IT_AGAIN(obj);
      }
      return true;
    } else {
      (await TOO_BAD_BUT(obj, "locked"));
    }
    await THIS_IS_IT(obj);
    return false;
  }
}

