async function V_WALK_TO() {
  let l = 0, val = 0;
  l = await META_LOC(g.PRSO);
  if (hasFlag(g.PRSO, PERSONBIT)) {
    if (eq(await META_LOC(g.WINNER), l) && !(hasFlag(g.PRSO, NDESCBIT))) {
      await BITE_YOU();
      return true;
    } else if (!(l = await FOLLOW_LOC$())) {
      await WHO_KNOWS$(g.PRSO);
      return M_FATAL;
    }
  }
  if (hasFlag(g.PRSO, SECRETBIT) && !(l == g.PRSO)) {
    return await NO_FUN();
  } else if ((g.HERE == loc(g.WINNER)) && ((l == g.HERE) || (g.PRSO == PSEUDO_OBJECT || g.PRSO == WALL) || (!(loc(l) == ROOMS) && (await GLOBAL_IN$(g.PRSO, g.HERE))))) {
    return await WALK_WITHIN_ROOM();
  } else if (l == LOCAL_GLOBALS) {
    return await MORE_SPECIFIC();
  } else if (await TOUR$()) {
    return true;
  } else if (await apply(getProp(g.HERE, P.ACTION), M_EXIT)) {
    return true;
  } else if (g.PRSO == INTDIR) {
    return await V_WALK_AROUND();
  } else if (!(loc(g.PRSO) == ROOMS) && !(hasFlag(g.PRSO, TOUCHBIT))) {
    await WHO_KNOWS$(g.PRSO);
    return M_FATAL;
  } else if (await FAR_AWAY$(l)) {
    g.CLOCK_WAIT = true;
    tell(C(40));
    await HE_SHE_IT(g.WINNER, true);
    tell(" can't go there from here");
    if (!(l == GLOBAL_OBJECTS)) {
      tell(", at least not directly");
    }
    tell(".)\n");
    return true;
  } else if (!(g.WINNER == PLAYER)) {
    if (await GOTO(l)) {
      if (g.WINNER == g.FOLLOWER) {
        g.FOLLOWER = 0;
      }
      l = get(g.GOAL_TABLES, getProp(g.WINNER, P.CHARACTER));
      if (!(get(l, GOAL_S) == 0)) {
        await ESTABLISH_GOAL(g.WINNER, get(l, GOAL_F), get(l, GOAL_ENABLE));
      }
      await OKAY();
    }
    return true;
  } else {
    if (await SEE_INTO$(g.PRSO, false)) {
      val = await DIR_FROM(g.HERE, l);
      if (!(val == 0)) {
        if (M_FATAL == (await apply(getProp(g.HERE, P.ACTION), val))) {
          return M_FATAL;
        }
      }
      await GOTO(g.PRSO, false);
      return true;
    } else if (g.NOW_WEARING == 0) {
      await YOUR_ROOM_F(P.OUT);
      return M_FATAL;
    }
    tell("You go quickly toward");
    await PRINTT(l);
    tell(".\n");
    await ESTABLISH_GOAL(PLAYER, l);
    g.OHERE = g.HERE;
    setFlag(PLAYER, INVISIBLE);
    loop1: for (;;) {
      if (val = await FOLLOW_GOAL(PLAYER)) {
        break loop1;
      }
    }
    clearFlag(PLAYER, INVISIBLE);
    if (!(g.FOLLOWER == 0)) {
      await FRIEND_FOLLOWS_YOU(g.HERE);
    }
    if (!(g.OHERE == g.HERE)) {
      await ENTER_ROOM();
    }
    return val;
  }
}

