async function FOLLOW_GOAL(person) {
  let heer = loc(person), gt = 0, goal = 0, flg = 0, igoal = false, x = 0;
  if (!(loc(heer) == ROOMS)) {
    heer = await META_LOC(heer);
    move(person, heer);
  }
  gt = get(g.GOAL_TABLES, getProp(person, P.CHARACTER));
  if (heer == get(gt, GOAL_F)) {
    return await GOAL_REACHED(person);
  } else if (get(gt, GOAL_ENABLE) == 0) {
    return false;
  }
  igoal = get(gt, GOAL_I);
  goal = get(g.TRANSFER_TABLE, igoal);
  if (goal == 0) {
    igoal = false;
    goal = get(gt, GOAL_S);
  }
  x = getProp(heer, P.STATION);
  if (!(heer == goal || heer == x)) {
    return await MOVE_PERSON(person, x);
  } else if (!goal) {
    return false;
  } else if (heer == goal) {
    if (igoal) {
      flg = get(g.TRANSFER_TABLE, igoal + 1);
      flg = await MOVE_PERSON(person, flg);
      await ESTABLISH_GOAL(person, get(gt, GOAL_F));
      return flg;
    } else if (!(heer == (flg = get(gt, GOAL_F)))) {
      return await MOVE_PERSON(person, flg);
    } else {
      return await GOAL_REACHED(person);
    }
  } else if (heer == getProp(goal, P.STATION)) {
    return await MOVE_PERSON(person, goal);
  }
  flg = await FOLLOW_GOAL_NEXT(heer, goal);
  return await MOVE_PERSON(person, flg);
}

async function FOLLOW_GOAL_NEXT(heer, goal) {
  let line = 0, cnt = 1, rm = 0, goal_flag = false, loc_ = 0, g_ = 0;
  line = await GET_LINE(getProp(goal, P.LINE));
  g_ = getProp(goal, P.STATION);
  for (;;) {
    rm = get(line, cnt);
    if (rm == heer) {
      if (goal_flag) {
        loc_ = get(line, cnt - 3);
      } else {
        loc_ = get(line, cnt + 3);
      }
      return loc_;
    } else if (rm == g_) {
      goal_flag = true;
    }
    cnt = cnt + 3;
  }
}

