async function COMPASS_EQV(rm, dir) {
  let dirtbl = 0, dirl = 0, p_ = 0, l = 0, tbl = 0, val = false;
  if (!(dir == P.UP || dir == P.DOWN) && !(dir == P.IN || dir == P.OUT)) {
    return dir;
  }
  dirtbl = getPropAddr(rm, dir);
  dirl = propSize(dirtbl);
  p_ = 0;
  loop1: for (;;) {
    if (val) {
      return val;
    } else if ((p_ = nextProp(rm, p_)) == 0) {
      return false;
    } else if (!(p_ < LOW_DIRECTION)) {
      tbl = getPropAddr(rm, p_);
      l = propSize(tbl);
      if (!(l == dirl)) {
        continue loop1;
      }
      --l;
      loop2: for (;;) {
        if (!(eq(getb(tbl, l), getb(dirtbl, l)))) {
          break loop2;
        } else if (--l < 0) {
          val = p_;
          break loop2;
        }
      }
    }
  }
}

async function DIR_EQV$(rm, dir1, dir2) {
  let dir1tbl = 0, dir2tbl = 0, l = 0;
  if (dir1 == dir2) {
    return true;
  } else if ((dir1tbl = getPropAddr(rm, dir1)) == 0) {
    return false;
  } else if ((dir2tbl = getPropAddr(rm, dir2)) == 0) {
    return false;
  }
  l = propSize(dir1tbl);
  if (!(l == propSize(dir2tbl))) {
    return false;
  }
  --l;
  for (;;) {
    if (!(eq(getb(dir1tbl, l), getb(dir2tbl, l)))) {
      return false;
    } else if (--l < 0) {
      return true;
    }
  }
}

async function DIR_FROM(here, there) {
  let v_ = false, p_ = 0, d_ = 0;
  if (await DIR_FROM_TEST(here, there, P.UP)) {
    return P.UP;
  } else if (await DIR_FROM_TEST(here, there, P.DOWN)) {
    return P.DOWN;
  } else if (await DIR_FROM_TEST(here, there, P.IN)) {
    return P.IN;
  } else if (await DIR_FROM_TEST(here, there, P.OUT)) {
    return P.OUT;
  }
  p_ = 0;
  for (;;) {
    if ((p_ = nextProp(here, p_)) < LOW_DIRECTION) {
      return v_;
    } else if (d_ = await DIR_FROM_TEST(here, there, p_)) {
      if ((d_ < LOW_DIRECTION) && !v_) {
        v_ = p_;
      } else {
        return p_;
      }
    }
  }
}

async function DIR_FROM_TEST(here, there, p_) {
  let l = 0, tbl = 0;
  if ((tbl = getPropAddr(here, p_)) == 0) {
    return false;
  }
  l = propSize(tbl);
  if ((l == DEXIT || l == UEXIT || l == CEXIT) && eq(getb(tbl, REXIT), there)) {
    return p_;
  } else {
    return false;
  }
}

