async function LORD_INTRO() {
  g.FOLLOWER = LORD;
  setFlag(LORD, TOUCHBIT);
  setFlag(LORD, SEENBIT);
  clearFlag(LORD, NDESCBIT);
  g.QCONTEXT = LORD;
  await THIS_IS_IT(LORD);
  tell("\"Here comes Jack now!\" exclaims ", D(FRIEND), ", as he comes striding toward you. ");
  await COMMON_DESC(LORD);
  tell("\n\"My fiance, ", D(LORD), C(32), S(g.TRESYLLIAN), ",\" ", D(FRIEND), S(g.INTRODUCES), "him. \"Jack, this is my friend from the States, ");
  await TELL_FULL_NAME();
  tell(".\"\n\"So you're that famous young sleuth whom the Yanks call ");
  if (g.GENDER_KNOWN == 0) {
    tell("Young ");
  } else {
    await TITLE();
  }
  tell("Sherlock!\" says ", D(LORD));
  if ((g.GENDER_KNOWN == 0) || !(hasFlag(PLAYER, FEMALE))) {
    tell(", shaking hands");
  }
  tell(". \"Tammy's told me about the mysteries you've solved");
  if (g.GENDER_KNOWN == 0) {
    tell(". She seems to think you can unravel the mystery of ", D(CASTLE), ".\"\n");
    return true;
  } else if (hasFlag(PLAYER, FEMALE)) {
    tell(" -- but she never let on you looked so smashing! Welcome to Cornwall, ");
    await PRINT_NAME(g.FIRST_NAME);
    tell(" luv!\"\nBefore you know it, he sweeps you into his arms and kisses you warmly! Let's hope ", D(FRIEND), " doesn't mind -- but for the moment all you can see are ", D(LORD), "'s dazzling sapphire-blue eyes.\n");
    return true;
  } else {
    tell("!\"\nHis keen blue eyes size you up with a friendly twinkle. Yet his friendliness seems to be all on the surface -- it may take time to figure out where His Lordship's really coming from.\n");
    return true;
  }
}

async function TELL_FULL_NAME() {
  await TITLE();
  await PRINT_NAME(g.FIRST_NAME);
  if (!(g.MIDDLE_WORD == 0)) {
    if (!(g.MIDDLE_WORD == W.COMMA)) {
      tell(C(32));
    }
    printB(g.MIDDLE_WORD);
  }
  tell(C(32));
  await PRINT_NAME(g.LAST_NAME);
  return await TELL_SUFFIX();
}

