async function LORD_GHOST_STORY() {
  tell("\"No use asking ME, ");
  if (await PRINT_NAME(g.FIRST_NAME)) {
    tell(C(46));
  }
  tell(" All I caught was", S(g.WHITISH_GLIMPSE), ". ");
  if (g.VARIATION == DOCTOR_C || g.VARIATION == PAINTER_C) {
    tell("I couldn't even swear it was a woman; it might've been some bloke in drag.\"\n");
    return true;
  } else {
    setFlag(GHOST_NEW, PERSONBIT);
    tell("She was blonde, definitely female, and about Dee's height...\"\n", D(LORD), "'s own face is pale as he adds, \"So, yes, it COULD have been her ghost... or Dee herself.\"\n");
    return true;
  }
}

async function LORD_F(arg = false) {
  let obj = 0, x = 0;
  if (arg == M_WINNER) {
    if (!(await GRAB_ATTENTION(LORD))) {
      return M_FATAL;
    } else if (isVerb(V.DESCRIBE) && (g.PRSO == GHOST_NEW) && !(g.VARIATION == FRIEND_C)) {
      await LORD_GHOST_STORY();
      return true;
    } else if (isVerb(V.ANSWER, V.REPLY) && (3 == g.LIONEL_SPEAKS_COUNTER)) {
      g.WINNER = PLAYER;
      await PERFORM(V.ASK_ABOUT, LORD, ARTIFACT);
      return true;
    } else if (x = await COM_CHECK(LORD)) {
      if (x == M_FATAL) {
        return false;
      } else if (x == M_OTHER) {
        return M_FATAL;
      } else {
        return true;
      }
    } else {
      await WHY_ME();
      return M_FATAL;
    }
  } else if (obj = await ASKING_ABOUT$(LORD)) {
    if (!(await GRAB_ATTENTION(LORD, obj))) {
      return M_FATAL;
    } else if (obj == ACCIDENT) {
      tell("Jack takes a deep breath. \"You've heard the bare facts, I assume -- she was in the ", D(BASEMENT), ", slipped and fell down the well. The evidence proves what happened: a tent pole she'd stumbled over; her one shoe that came off, with the slippery sole and the loose heel; and of course ", D(NECKLACE_OF_D), ". I even", S(g.FOUND_FABRIC), "\"\nHe adds, \"The police never found ", D(CORPSE), ". But the well is drawing tide water. No doubt she was swept out to sea.\"\n");
      return true;
    } else if (obj == ARTIFACT) {
      tell("Jack fidgets and replies, \"Well, ah, we've all HEARD of it, certainly. Uncle Lionel liked to drop teasing hints about how valuable it was. But he was frightfully secretive. He never identified it.");
      if (!(g.LIONEL_SPEAKS_COUNTER == INIT_LIONEL_SPEAKS_COUNTER)) {
        tell(" He's probably playing the same silly game right now.");
        if (!(g.LIONEL_SPEAKS_COUNTER == 0)) {
          tell(" Let's hear the old boy out.");
        }
      }
      tell("\"\n");
      return true;
    } else if (obj == CASTLE) {
      tell("\"Well, as I daresay you've heard, the castle's been infested lately with a spook. And it seems bent on harming ", D(FRIEND), ". All in all, a very rum go.\"\n");
      return true;
    } else if ((obj == g.SEARCHER) && (!(g.CONFESSED == 0) || !(get(g.TOLD_ABOUT_EVID, LORD_C) == 0)) && !(LORD == g.SEARCHER)) {
      tell(S(g.IM_SHOCKED));
      return true;
    } else if (obj == FRIEND || obj == ROMANCE) {
      tell("\"She's a darling girl, really first-rate.");
      if (g.VARIATION == FRIEND_C) {
        if (eq(loc(LORD), g.HERE, PSEUDO_OBJECT)) {
          tell("\" He whispers, \"");
        } else {
          tell(C(32));
        }
        tell("Although lately she's seemed cool toward me.");
      }
      tell("\"\n");
      return true;
    } else if ((obj == GHOST_NEW || obj == DANGER || obj == HAUNTING) && !(g.VARIATION == FRIEND_C)) {
      await LORD_GHOST_STORY();
      return true;
    } else if ((obj == CLUE_2) && !(g.VARIATION == LORD_C) && !(loc(obj) == LORD)) {
      await CLUE_2_STORY(LORD);
      return true;
    } else if (obj == LENS || obj == LENS_1 || obj == LENS_2) {
      await HE_SHE_IT(LORD, true);
      tell(" gives a puzzled shrug, saying, \"");
      tell("There's nothing wrong with my eyesight.\"\n");
      return true;
    } else if ((obj == MAID) && hasFlag(LETTER, TOUCHBIT)) {
      tell(S(g.JACK_THINKS_GLADYS), "\"\n");
      return true;
    } else if ((obj == PASSAGE) && (get(g.FOUND_PASSAGES, LORD_C) == 0)) {
      tell("\"Hmm... good question. I know there are old tales about ", D(CASTLE), " being honeycombed with ", D(PASSAGE), "s, but I've never actually stumbled on any. Uncle Lionel would have known, but I never asked him before he died, worse luck.\"\n");
      return true;
    } else if (obj == PRIEST_DOOR) {
      tell("\"It's in the ", D(DUNGEON), ", close to the curtain wall. Dee used it because her cottage is just down the shore.\"\nHe adds, \"By the way, the name '", D(PRIEST_DOOR), "' dates back to when the Catholic Church was outlawed in England, and priests had to hide for fear of execution. Many British great houses have ", D(PASSAGE), "s, hiding places, and entrances.\"\n");
      return true;
    } else if (x = await COMMON_ASK_ABOUT(LORD, obj)) {
      if (x == M_FATAL) {
        return false;
      } else {
        return true;
      }
    } else {
      return await TELL_DUNNO(LORD, obj);
    }
  } else if (isVerb(V.KISS, V.RUB)) {
    if (loc(FRIEND) == g.HERE) {
      putProp(FRIEND, P.LINE, 1 + getProp(FRIEND, P.LINE));
      await HE_SHE_IT(FRIEND, true);
      tell(" flashes you an angry look.\n");
    }
    if (hasFlag(PLAYER, FEMALE)) {
      await UNSNOOZE(LORD);
      putProp(LORD, P.LINE, 0);
      putProp(LORD, P.LDESC, 0);
      tell("\"I say! You Americans are frightfully friendly!\" says ", D(LORD), ".\n");
      return true;
    } else {
      return false;
    }
  } else {
    return await PERSON_F(LORD, arg);
  }
}

