async function JACK_TAPE_F() {
  let p_ = 0;
  if (isVerb(V.LAMP_ON, V.LISTEN, V.PLAY)) {
    tell("First you hear Lionel: \"This ", D(JACK_TAPE), " should capture any sound in the ", D(JACK_ROOM), " when I run it. Testing, testing,...\"\nThen you hear Lionel tell ", D(LOVER), " that he suspects Jack of coveting the inheritance and wanting to kill him.\nAfter a pause, Jack tells Lionel, with a cold-blooded chuckle, that his time has come. Then ", S(g.LIONELS_VOICE), " is urgent and muffled, as if he's being smothered! He calls out, \"Jack! Stop!\" and then... silence.\n");
    p_ = first(g.HERE);
    if (!(p_ == 0)) {
      await FOUND_PASSAGES_REPEAT(p_, JACK_TAPE, g.TOLD_ABOUT_EVID);
    }
    if ((loc(FRIEND) == g.HERE) && !(g.CAPTOR == FRIEND)) {
      await THIS_IS_IT(FRIEND);
      move(FRIEND, TAMARA_ROOM);
      put(g.FOLLOW_LOC, FRIEND_C, TAMARA_ROOM);
      if (g.FOLLOWER == FRIEND || g.FOLLOWER == LORD) {
        g.FOLLOWER = 0;
      }
      put(get(g.GOAL_TABLES, getProp(FRIEND, P.CHARACTER)), GOAL_ENABLE, 0);
      putProp(FRIEND, P.LDESC, 7);
      tell(D(FRIEND), "'s eyes fill with tears, and she runs to her room.\n");
    }
    if (g.EVIDENCE_FOUND == 0) {
      await CONGRATS();
    }
    g.EVIDENCE_FOUND = JACK_TAPE;
    if (!(g.CONFESSED == 0)) {
      return true;
    } else if (loc(LORD) == g.HERE) {
      await CONFESSION(LORD);
    } else if (p_ = await FIND_FLAG_HERE_NOT(PERSONBIT, MUNGBIT, g.WINNER)) {
      g.WINNER = PLAYER;
      await PERFORM(V.ASK_ABOUT, p_, JACK_TAPE);
    }
    return true;
  } else {
    return false;
  }
}

