async function WILLING$(per, kiss = false) {
  if (kiss == 0) {
    if (BED_TIME < g.PRESENT_TIME) {
      return false;
    } else if (await QUEUED$(I_TOUR.id)) {
      return false;
    } else if ((g.HERE == DINING_ROOM) || (await QUEUED$(I_DINNER_SIT.id))) {
      return false;
    } else if (per == g.CONFESSED || per == g.CAPTOR) {
      return false;
    } else {
      return true;
    }
  } else if (per == FRIEND) {
    if (!(g.VARIATION == FRIEND_C)) {
      return true;
    } else {
      return false;
    }
  } else if (per == BUTLER) {
    if (isVerb(V.EMPTY) && !(g.HERE == YOUR_ROOM)) {
      return false;
    } else if (isVerb(V.FOLLOW)) {
      return false;
    } else {
      return true;
    }
  } else if (!(g.GENDER_KNOWN == 0)) {
    if (per == DEB) {
      if (!(hasFlag(PLAYER, FEMALE))) {
        return true;
      } else {
        return false;
      }
    } else if (per == OFFICER) {
      if (hasFlag(PLAYER, FEMALE)) {
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

