async function DOCTOR_F(arg = 0) {
  let obj = 0, x = 0;
  if (arg == M_WINNER) {
    if ((g.AWAITING_REPLY == DOCTOR_C) && isVerb(V.YES, V.NO)) {
      putProp(DOCTOR, P.LDESC, 0);
      putProp(DOCTOR, P.LINE, 0);
      g.AWAITING_REPLY = false;
      tell("\"I see...\"\n");
      return true;
    } else if (!(await GRAB_ATTENTION(DOCTOR))) {
      return M_FATAL;
    } else if (isVerb(V.DESCRIBE) && (g.PRSO == GHOST_NEW) && (g.VARIATION == DOCTOR_C)) {
      tell(D(DOCTOR), " shrugs, with a look of distaste, as if he'd like to forget the episode. \"");
      tell("I'm afraid I can't tell you any more, ");
      if (await TITLE_NAME()) {
        tell(C(46));
      }
      tell(" I assumed the ghost was ", D(LOVER), ". It certainly looked like her: a blonde, attractive young woman. If it WASN'T ", D(LOVER), ", it was a convincing imposture.\"\n");
      return true;
    } else if (await DIVESTMENT$(MUSTACHE)) {
      if (g.VARIATION == DOCTOR_C) {
        tell(S(g.MUSTACHE_STORY));
        return true;
      } else {
        return await HAR_HAR();
      }
    } else if (x = await COM_CHECK(DOCTOR)) {
      if (x == M_FATAL) {
        return false;
      } else if (x == M_OTHER) {
        return M_FATAL;
      } else {
        return true;
      }
    } else {
      await WHY_ME();
      return M_FATAL;
    }
  } else if (obj = await ASKING_ABOUT$(DOCTOR)) {
    if (!(await GRAB_ATTENTION(DOCTOR, obj))) {
      return M_FATAL;
    } else if ((obj == g.SEARCHER) && (!(g.CONFESSED == 0) || !(get(g.TOLD_ABOUT_EVID, DOCTOR_C) == 0)) && !(DOCTOR == g.SEARCHER)) {
      tell(S(g.IM_SHOCKED));
      return true;
    } else if (obj == COUSIN || obj == BUST) {
      tell("\"He loved me as a brother.\"\n");
      return true;
    } else if ((obj == GHOST_NEW || obj == DANGER || obj == HAUNTING) && (g.VARIATION == DOCTOR_C)) {
      tell("The doctor pauses, looking troubled, as if reluctant to speak, or perhaps marshaling his thoughts.\n\"On the very night after ", D(ACCIDENT), ",\" he says at last, \"I couldn't sleep. I suppose the tragedy was on my mind. That and the medical cases I have in my London clinic for rare diseases. Anyhow, I took a stroll out in the ", D(COURTYARD), ". The fresh sea breeze was very soothing. When I went back inside, I felt ready for sleep. I went in through the ", D(OLD_GREAT_HALL), ", you see.\"\nHe goes on, \"Then I saw this ghostly figure in white -- Good Lord, what a shock it gave me! I couldn't move for a moment; I thought ", D(LOVER), " had come back from the dead. As I stood there, staring, the ghost flitted off toward the ", D(BASEMENT), "... I felt no impulse to go after it, I might add.\"\n");
      return true;
    } else if (obj == LENS || obj == LENS_1 || obj == LENS_2) {
      tell(C(34));
      if ((g.VARIATION == DOCTOR_C || g.VARIATION == PAINTER_C) && !(g.FOUND_IT_PERM == 0)) {
        tell("Not mine. ");
      }
      tell("As you see, I wear glasses at all times,\" he says.\n");
      return true;
    } else if ((obj == MUSTACHE) && (g.VARIATION == DOCTOR_C)) {
      tell(S(g.MUSTACHE_STORY));
      return true;
    } else if (obj == WENDISH_STUFF) {
      tell("\"I always bring them along.\"\n");
      return true;
    } else if (x = await COMMON_ASK_ABOUT(DOCTOR, obj)) {
      if (x == M_FATAL) {
        return false;
      } else {
        return true;
      }
    } else {
      return await TELL_DUNNO(DOCTOR, obj);
    }
  } else {
    return await PERSON_F(DOCTOR, arg);
  }
}

