async function DESCRIBE_PERSON(per) {
  let str = false;
  str = getProp(per, P.LDESC);
  if (!(per == BUTLER || per == LOVER) && (await ALL_TOGETHER_NOW$())) {
    if (per == LORD) {
      g.P_HIM_OBJECT = false;
      g.P_HER_OBJECT = false;
      tell(D(per), " and all his guests are here.");
      if ((g.CONFESSED == 0) && !(await QUEUED$(I_LIONEL_SPEAKS.id))) {
        tell(" They smile pleasantly but, with typical British reserve, seem willing to leave you to your own devices.");
      }
      crlf();
    }
    return true;
  }
  if (str) {
    put(g.TOUCHED_LDESCS, getProp(per, P.CHARACTER), str);
    return false;
  }
  await START_SENTENCE(per);
  tell(" is ");
  if ((str = getPropAddr(per, P.WEST)) && (str = get(str, NEXITSTR))) {
    tell(S(str));
  }
  tell(".");
  if (str == 6) {
    printC(32);
  } else {
    crlf();
  }
  return true;
}

