async function PERSON_F(per, arg) {
  let obj = 0, x = 0, l = 0, c_ = 0, n_ = 0;
  l = loc(per);
  c_ = getProp(per, P.CHARACTER);
  if (isVerb(V.ALARM, V.SHAKE)) {
    if (g.PRSO == per) {
      if ((await QUEUED$(I_COME_TO.id)) && (per == g.VILLAIN_PER || per == GHOST_NEW)) {
        await QUEUE(I_COME_TO.id, 1);
        return true;
      } else if (await UNSNOOZE(per, true)) {
        await HE_SHE_IT(per, true);
        tell(" gasps to see you so close!\n");
        return true;
      } else {
        (await HE_SHE_IT(per, true, "is"));
        tell(" still ");
        if (x = getProp(per, P.LDESC)) {
          tell(S(get(g.LDESC_STRINGS, x)));
        } else if (x = getPropAddr(per, P.WEST)) {
          tell(S(get(x, NEXITSTR)));
        }
        tell(".\n");
        return true;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.FORGIVE)) {
    if (!(await GRAB_ATTENTION(per))) {
      return M_FATAL;
    }
    tell("\"Thank you so much. I didn't realize I'd offended you.\"\n");
    return true;
  } else if (isVerb(V.GIVE)) {
    if ((g.PRSI == per) && (await HELD$(g.PRSO))) {
      if (!(await GRAB_ATTENTION(per))) {
        return M_FATAL;
      }
      return false;
    } else {
      return false;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (!(getProp(per, P.LINE) == 0)) {
      tell("Seems you've already done that.\n");
      return true;
    } else {
      return await WONT_HELP();
    }
  } else if (isVerb(V.MUNG, V.SEARCH, V.SEARCH_FOR)) {
    if ((per == g.PRSO) && hasFlag(per, PERSONBIT) && !(hasFlag(per, MUNGBIT))) {
      putProp(per, P.LINE, 1 + getProp(per, P.LINE));
      if (!(eq(getProp(per, P.LDESC), 4))) {
        putProp(per, P.LDESC, 20);
      }
      await HE_SHE_IT(per, true);
      tell(" pushes you away and mutters, \"I don't think that's called for.\"\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.SHOW)) {
    if (per == g.PRSO) {
      if (!(await GRAB_ATTENTION(per))) {
        return M_FATAL;
      } else {
        await PERFORM(V.TELL_ABOUT, g.PRSO, g.PRSI);
        return true;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.SMILE)) {
    if (per == g.PRSO) {
      if (!(await GRAB_ATTENTION(per))) {
        return M_FATAL;
      } else {
        (await HE_SHE_IT(g.PRSO, true, "smile"));
        tell(" back at you.\n");
        return true;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.TELL_ABOUT)) {
    if (per == g.PRSO) {
      if (!(await GRAB_ATTENTION(per))) {
        return M_FATAL;
      }
      putProp(per, P.LDESC, 12);
      if (hasFlag(g.PRSI, RMUNGBIT) && hasFlag(g.PRSI, SEENBIT) && !(hasFlag(g.PRSI, PERSONBIT))) {
        put(g.TOLD_ABOUT_EVID, getProp(per, P.CHARACTER), true);
        tell(S(g.THATS_INTERESTING));
        return true;
      } else if (g.PRSI == CLUE_1) {
        tell(S(g.THATS_INTERESTING));
        return true;
      } else if (g.PRSI == g.CONFESSED) {
        if (!(per == g.CONFESSED)) {
          tell(S(g.IM_SHOCKED));
          return true;
        }
      } else if (g.PRSI == GHOST_NEW) {
        if (hasFlag(GHOST_NEW, TOUCHBIT) && !(per == GHOST_NEW)) {
          put(g.TOLD_ABOUT_GHOST, getProp(per, P.CHARACTER), true);
          tell("\"You saw the ghost? Tell me, how can I help?\"\n");
          return true;
        }
      } else if (await SECRET_PASSAGE_OR_DOOR$(g.PRSI)) {
        await TELL_ABOUT_OBJECT(g.PRSO, PASSAGE, g.FOUND_PASSAGES);
        return true;
      }
      tell("\"I don't know what you mean.\"\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.THROW_AT)) {
    if ((per == g.PRSI) && hasFlag(per, PERSONBIT) && !(hasFlag(per, MUNGBIT))) {
      move(g.PRSO, g.PRSI);
      await HE_SHE_IT(per, true);
      tell(" catches");
      await PRINTT(g.PRSO);
      tell(" with");
      await HIM_HER_IT(per, false, true);
      tell(C(32));
      if (per == DEB || per == DOCTOR) {
        tell("lef");
      } else {
        tell("righ");
      }
      tell("t hand.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return await COMMON_OTHER(per);
  }
}

