async function COM_CHECK(per) {
  let n_ = 0, tag = 0;
  n_ = getProp(per, P.LINE);
  tag = get(g.TOLD_ABOUT_GHOST, getProp(per, P.CHARACTER));
  if (isVerb(V.$CALL)) {
    await DONT_UNDERSTAND();
    return M_OTHER;
  } else if (await TRANSIT_TEST(per)) {
    return M_FATAL;
  } else if (isVerb(V.ALARM, V.HELLO, V.SORRY)) {
    if ((g.PRSO == ROOMS) || (g.PRSO == per)) {
      g.WINNER = PLAYER;
      await PERFORM(g.PRSA, per);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ARREST, V.NO, V.THANKS, V.YES)) {
    return M_FATAL;
  } else if (isVerb(V.DESCRIBE)) {
    if (g.PRSO == GHOST_NEW) {
      tell("\"I'm sorry, but I didn't see");
      await HIM_HER_IT(GHOST_NEW);
      tell(".\"\n");
      return true;
    } else if (g.PRSO == MAID) {
      tell(S(g.NEVER_NOTICED_HER));
      return true;
    } else if (g.PRSO == BUST || g.PRSO == COUSIN) {
      await WINNER_DESCRIBE(BUST, DINING_ROOM);
      return true;
    } else if (g.PRSO == LOVER) {
      await WINNER_DESCRIBE(LOVER_PIC, DRAWING_ROOM);
      return true;
    } else {
      tell("\"You could ");
      if (!(eq(await META_LOC(g.PRSO), g.HERE))) {
        tell("go ");
      }
      tell("have a look for ", D(PLAYER), ", you know.\"\n");
      return true;
    }
  } else if (isVerb(V.FOLLOW, V.WALK_TO)) {
    if (per == BUTLER) {
      return false;
    } else if (isVerb(V.WALK_TO) && (!(tag == 0) || (g.PRSO == TAMARA_BED || g.PRSO == BED || g.PRSO == SLEEP_GLOBAL))) {
      return M_FATAL;
    } else {
      tell("\"I will go where I please, thank you very much.\"\n");
      return true;
    }
  } else if (isVerb(V.INVENTORY)) {
    if (!(await CARRY_CHECK(per))) {
      (await HE_SHE_IT(per, true, "is"));
      tell("n't holding anything.\n");
    }
    return true;
  } else if (isVerb(V.LISTEN)) {
    if ((g.PRSO == PLAYER_NAME || g.PRSO == PLAYER) || !(loc(g.PRSO) == GLOBAL_OBJECTS)) {
      tell("\"I'm trying to, ");
      await PRINT_NAME(g.FIRST_NAME);
      tell("!\"\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.RUB)) {
    await FACE_RED();
    return true;
  }
  if ((random(3) == 1) && (await WILLING$(per, true))) {
    if (per == DEB) {
      g.FAWNING = true;
      tell("\"My dear ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(", how could I refuse someone as handsome as you?\" Iris murmurs, batting her eyelashes. ");
    } else if (per == OFFICER) {
      g.FAWNING = true;
      tell("\"Delighted to help you if I can, ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(" luv! One feels those great luminous eyes of yours can see right through a chap!\" says the handsome young guardsman. ");
    }
  }
  if (isVerb(V.DANCE) && (g.PRSO == PLAYER)) {
    g.WINNER = PLAYER;
    await PERFORM(g.PRSA, per);
    return true;
  } else if (isVerb(V.DANCE) || (isVerb(V.WALK) && ((g.PRSO == P.OUT) || !(tag == 0)))) {
    return M_FATAL;
  } else if (isVerb(V.SIGN)) {
    tell("You notice that");
    await HE_SHE_IT(per);
    tell(" is ");
    if (per == DEB || per == DOCTOR) {
      tell("lef");
    } else {
      tell("righ");
    }
    tell("t-handed.\n");
    return true;
  } else if (isVerb(V.KISS)) {
    await UNSNOOZE(per);
    tell("\"I really don't think this is the proper time or place.\"\n");
    return true;
  } else if (isVerb(V.TAKE)) {
    if (loc(g.PRSO) == PLAYER) {
      g.WINNER = PLAYER;
      await PERFORM(V.GIVE, g.PRSO, per);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.READ)) {
    if (loc(g.PRSO) == PLAYER) {
      g.WINNER = PLAYER;
      await PERFORM(V.SHOW, per, g.PRSO);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.FORGIVE)) {
    g.WINNER = g.PRSO;
    await PERFORM(V.SORRY, per);
    return true;
  } else if (isVerb(V.GIVE, V.THROW_AT) && hasFlag(g.PRSI, PERSONBIT)) {
    g.WINNER = g.PRSI;
    await PERFORM(V.ASK_FOR, per, g.PRSO);
    return true;
  } else if (isVerb(V.SGIVE) && hasFlag(g.PRSO, PERSONBIT)) {
    g.WINNER = g.PRSO;
    await PERFORM(V.ASK_FOR, per, g.PRSI);
    return true;
  } else if (isVerb(V.HELP)) {
    if (g.PRSO == false || g.PRSO == PLAYER || g.PRSO == PLAYER_NAME) {
      g.WINNER = PLAYER;
      await PERFORM(V.ASK, per);
      return true;
    } else {
      return M_FATAL;
    }
  } else if (isVerb(V.FIND, V.SHOW, V.SSHOW)) {
    if (isVerb(V.SHOW)) {
      g.PRSA = V.SSHOW;
      n_ = g.PRSI;
      g.PRSI = g.PRSO;
      g.PRSO = n_;
    }
    if (loc(g.PRSO) == ROOMS) {
      g.WINNER = PLAYER;
      await PERFORM(V.WALK_TO, g.PRSO);
      return true;
    } else if (loc(g.PRSO) == per) {
      if (eq(await ITAKE(), true)) {
        await HE_SHE_IT(per, true);
        tell(" fumbles in");
        await HIM_HER_IT(per, false, true);
        tell(" pocket and produces");
        await HIM_HER_IT(g.PRSO);
        tell(".\n");
      }
      return true;
    } else if (isVerb(V.FIND)) {
      return M_FATAL;
    } else {
      return false;
    }
  } else if (isVerb(V.PLAY)) {
    if (g.PRSO == PIANO) {
      tell("\"I'm not very good at this sort of thing, but...\"\n");
      return M_FATAL;
    } else {
      return false;
    }
  } else if (isVerb(V.TELL)) {
    if (g.PRSO == PLAYER_NAME || g.PRSO == PLAYER) {
      g.WINNER = PLAYER;
      await PERFORM(V.ASK, per);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.TELL_ABOUT)) {
    if (hasFlag(g.PRSO, PERSONBIT)) {
      g.WINNER = PLAYER;
      await PERFORM(V.ASK_ABOUT, per, g.PRSI);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.STOP, V.WAIT_FOR)) {
    if ((g.PRSO == ROOMS || g.PRSO == PLAYER_NAME) || (g.PRSO == PLAYER || g.PRSO == GLOBAL_HERE || g.PRSO == g.HERE)) {
      if (per == g.FOLLOWER) {
        g.FOLLOWER = 0;
        tell("\"As you wish, ");
        if (await PRINT_NAME(g.FIRST_NAME)) {
          tell(C(46));
        }
        tell("\"\n");
        return true;
      } else {
        g.WINNER = PLAYER;
        await PERFORM(V.$CALL, per);
        return true;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.TALK_ABOUT)) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, per, g.PRSO);
    return true;
  } else {
    return false;
  }
}

async function EVIDENCE$(obj, per = 0) {
  if (!(per == 0) && !(g.VARIATION == getProp(per, P.CHARACTER))) {
    return false;
  } else if (obj == LETTER_MAID || obj == PASSAGE || obj == JEWEL) {
    return true;
  } else if (obj == LENS || obj == LENS_1 || obj == LENS_2) {
    return true;
  } else if (obj == COSTUME || obj == LENS_BOX || obj == EARRING) {
    return true;
  } else if (obj == BLOWGUN) {
    return true;
  } else if (!(obj == 0) && !(hasFlag(obj, PERSONBIT)) && hasFlag(obj, RMUNGBIT)) {
    return true;
  } else {
    return false;
  }
}

async function SETUP_SHOT(per) {
  g.VILLAIN_KNOWN$ = true;
  move(BLOWGUN, per);
  clearFlag(BLOWGUN, NDESCBIT);
  clearFlag(BLOWGUN, TAKEBIT);
  putProp(per, P.LINE, 2);
  putProp(per, P.LDESC, 8);
  g.AIMED_HERE = g.HERE;
  g.SHOOTER = per;
  return await QUEUE(I_SHOT.id, g.CLOCKER_RUNNING);
}

async function COMMON_ASK_ABOUT(per, obj) {
  if (await EVIDENCE$(obj, per)) {
    await HE_SHE_IT(per, true);
    tell(" flinches a little before answering.\n");
  } else if (await EVIDENCE$(obj)) {
    if (!(g.CONFESSED == 0)) {
      tell(S(g.IM_SHOCKED));
      return true;
    } else {
      await HE_SHE_IT(per, true);
      tell(" says, \"");
      if (random(2) == 1) {
        tell("Good Lord");
      } else {
        tell("I say");
      }
      tell("! I think you're onto something here.\"\n");
      return true;
    }
  }
  if (hasFlag(obj, RMUNGBIT) && isVerb(V.CONFRONT, V.SHOW) && !(hasFlag(obj, PERSONBIT))) {
    put(g.TOLD_ABOUT_EVID, getProp(per, P.CHARACTER), true);
  }
  if ((obj == g.SEARCHER) && eq(getProp(obj, P.LDESC), 21)) {
    if (per == g.SEARCHER) {
      tell("\"You mean, why am I searching? I'm sure you can guess.\"\n");
      return true;
    } else {
      tell("\"I imagine that ", D(obj), " is searching because");
      await THIS_IS_IT(obj);
      await HE_SHE_IT(obj);
      tell(" got a bright idea. I prefer to let our", S(g.FAMOUS_YOUNG_DETECTIVE), " do the work.\"\n");
      return true;
    }
  } else if (obj == per) {
    tell("\"I have no secrets. Anyone can see what I am.\"\n");
    return true;
  } else if (obj == PLAYER || obj == PLAYER_NAME) {
    tell("\"You're ");
    await TELL_FULL_NAME();
    tell(", the", S(g.FAMOUS_YOUNG_DETECTIVE), ".\"\n");
    return true;
  } else if (obj == BUTLER) {
    tell("\"He's served the family all his life.\"\n");
    return true;
  } else if (obj == LOVER) {
    tell("\"Poor thing, her life came to a sad ending.");
    if (per == DOCTOR) {
      tell(" As did her grandfather, whom I treated at my clinic.");
    }
    tell("\"\n");
    return true;
  } else if (obj == COUSIN || obj == BUST) {
    tell("\"He was a bit of a strange bird, was Lionel.\"\n");
    return true;
  } else if (obj == GHOST_NEW || obj == DANGER || obj == HAUNTING) {
    tell("\"I myself haven't seen");
    await HIM_HER_IT(GHOST_NEW);
    tell(".\"\n");
    return true;
  } else if (obj == GHOST_OLD) {
    tell("\"Oh, she has haunted ", D(CASTLE), " for centuries -- a lovely phantom in a white gown, with long pale hair. She was said to be the unfaithful wife of an early Lord ", S(g.TRESYLLIAN), ", who had her walled up alive in the tower.\"\n");
    return true;
  } else if (obj == MAID) {
    tell(S(g.NEVER_NOTICED_HER));
    return true;
  } else if (hasFlag(obj, PERSONBIT)) {
    return false;
  } else if ((g.VARIATION == getProp(per, P.CHARACTER)) && (hasFlag(obj, RMUNGBIT) || (obj == BLOWGUN))) {
    putProp(per, P.LINE, 2);
    tell("\"What can I say?\"");
    await HE_SHE_IT(per);
    tell(" shrugs. \"It's a fair cop. You've caught me with damning evidence.");
    if ((g.VARIATION == FRIEND_C || g.VARIATION == LORD_C) || !(g.HERE == get(g.CHAR_ROOM_TABLE, 1 + getProp(per, P.CHARACTER))) || (await FIND_FLAG_HERE(PERSONBIT, PLAYER, per))) {
      tell("\"\n");
      return true;
    }
    if (loc(BLOWGUN) == per) {
      tell("\" ");
      await HE_SHE_IT(per, true);
    } else {
      tell(" But there's something you don't know yet");
      await IAN_CALLS_YOU();
      tell(", which may put the matter in a different light.\"\nStill smiling,");
      await HE_SHE_IT(per);
      tell(" puts");
      await HIM_HER_IT(per, false, true);
      tell(" hand into");
      await PRINTT(g.HIDING_PLACE);
      tell(", and");
    }
    if (eq(loc(BLOWGUN), per, g.HIDING_PLACE)) {
      g.DISCOVERED_HERE = g.HERE;
      await SETUP_SHOT(per);
      if (!(hasFlag(BLOWGUN, NDESCBIT))) {
        tell(" takes");
      } else {
        clearFlag(BLOWGUN, NDESCBIT);
        tell(" suddenly extracts");
      }
      await PRINTT(BLOWGUN);
      tell(" and aims it at you!\n");
      return true;
    } else {
      await HIM_HER_IT(per, false, true);
      tell(" jaw drops as");
      await HIM_HER_IT(per, false, true);
      tell(" hand comes out, empty.\n");
      return true;
    }
  } else if (obj == ACCIDENT) {
    tell("\"You'd best ask Jack about that, or ", D(BUTLER), ".\"\n");
    return true;
  } else if (obj == BELL) {
    tell("\"It's actually a ship's bell off an old British man-o'-war.\"\n");
    return true;
  } else if ((per == g.SEARCHER) && (g.LIONEL_SPEAKS_COUNTER == 0) && (await SHOWING_CLUE$(obj)) && !(isVerb(V.ASK_ABOUT))) {
    await QUEUE(I_SEARCH.id, 1);
    tell(S(g.THATS_INTERESTING));
    return true;
  } else if (obj == CORPSE) {
    tell(C(34), D(CORPSE), " was never recovered from the well. They think it was carried out to sea by an underground tidal stream.\"\n");
    return true;
  } else if ((obj == COSTUME || obj == BLOWGUN || obj == LENS_BOX) && (((per == PAINTER || per == DOCTOR) && (g.VARIATION == getProp(per, P.CHARACTER))) || ((per == DEB) && (g.VARIATION == FRIEND_C)))) {
    obj = get(g.CHAR_ROOM_TABLE, 1 + getProp(per, P.CHARACTER));
    tell(D(per), "'s look changes to a puzzled and angry frown. ");
    if (!(per == LORD || per == FRIEND)) {
      tell("\"You mean you found that ");
      if (g.HERE == obj) {
        tell("here ");
      }
      tell("in my room?\"");
      await HE_SHE_IT(per);
      tell(" gasps. ");
    }
    tell("\"How can I explain it when it doesn't belong to me? If you didn't bring it ");
    if (!(g.HERE == obj)) {
      tell(C(116));
    }
    tell("here ", D(PLAYER), ", then someone else planted it, trying to frame me as the maniac who's been posing as ", D(LOVER), "'s ghost!\"\n");
    return true;
  } else if (obj == COSTUME) {
    if (!(get(g.FOUND_COSTUME, PLAYER_C) == 0)) {
      tell("\"So that's how ");
      if (g.CONFESSED == 0) {
        tell("somebody");
      } else {
        tell(D(g.VILLAIN_PER));
      }
      tell(" posed as a ghost!\"\n");
      return true;
    } else {
      return false;
    }
  } else if (obj == DINNER || obj == DINNER_2) {
    if (g.PRESENT_TIME < DINNER_TIME) {
      tell("\"Tonight's a dinner in honor of ");
      if (per == BUTLER) {
        tell("the late Lord ");
      }
      tell("Lionel's birthday. In his will, he asked for these particular guests -- except ");
      if (per == FRIEND) {
        tell("me");
      } else {
        printD(FRIEND);
      }
      tell(", of course. It's at eight o'clock");
      if (!(per == BUTLER)) {
        tell(" -- or whenever ", D(BUTLER), " gets 'round to it");
      }
      tell(".\"\n");
      return true;
    } else if (eq(await META_LOC(DINNER), g.HERE)) {
      tell("\"It looks delicious!\"\n");
      return true;
    } else {
      if (eq(getProp(per, P.LDESC), 10)) {
        tell("\"I'm enjoying");
      } else {
        tell("\"I enjoyed");
      }
      tell(" it immensely.");
      if (!(g.MISSED_DINNER == 0)) {
        tell(" We started without you, as we assumed you were sleuthing.");
      }
      tell("\"\n");
      return true;
    }
  } else if ((obj == BRICKS || obj == COFFIN || obj == CRYPT) || (obj == DUNGEON || obj == IRON_MAIDEN || obj == TOMB) || (obj == WELL)) {
    tell(S(g.ANCIENT_SECRETS), "\n");
    return true;
  } else if (obj == JEWEL) {
    await HE_SHE_IT(per, true);
    if ((per == FRIEND) && hasFlag(EARRING, LOCKED)) {
      tell(" says, \"Oh, thank you for finding it! I've looked everywhere!\"\n");
      return true;
    } else if (g.HERE == (await META_LOC(JEWEL))) {
      tell(" looks at it with interest");
      if (per == DEALER) {
        tell(", putting a monocle in one eye to see better");
      }
    } else {
      tell(" listens to your description of it");
    }
    tell(". But");
    await HE_SHE_IT(per);
    tell(" says");
    await HE_SHE_IT(per);
    tell(" can't identify it.\n");
    return true;
  } else if (obj == LAMP) {
    tell("\"I think ", D(BUTLER), " keeps");
    await IN_CASE_OF_BLACKOUT();
    return true;
  } else if ((obj == LUGGAGE) && (loc(LUGGAGE) == BUTLER)) {
    tell("\"Don't panic.");
    await BOLITHO_WILL();
    tell(".\"\n");
    return true;
  } else if (obj == MACE) {
    tell("\"That is a long story, ");
    if (await TITLE_NAME()) {
      tell(C(46));
    }
    tell(" When Lord Lionel was alive, he had a pit bulldog to protect the castle. A right vicious brute it was, too! Several times it attacked the servants, so the master gave out these ", D(MACE), "s. Just press the button on the side, and it sprays something foul. It always worked a treat on that wretched dog, and I daresay it could stop a ghost just as well.\"\n");
    return true;
  } else if (obj == NECKLACE_OF_D) {
    tell("\"The police returned it to ");
    if (per == LORD) {
      tell("me");
    } else {
      tell(D(LORD));
    }
    tell(" after the inquest.\"\n");
    return true;
  } else if (await SECRET_PASSAGE_OR_DOOR$(obj)) {
    return await TELL_ABOUT_OBJECT(per, PASSAGE, g.FOUND_PASSAGES);
  } else if (obj == SKELETON) {
    tell("\"Ugh! Those must be the bones of the ", D(GHOST_OLD), "!\"\n");
    return true;
  } else if (await TREASURE_FOUND$(obj, per)) {
    return true;
  } else if (obj == YOUR_ROOM) {
    tell("\"It's fortunate that one bedroom was available for you.\"\n");
    return true;
  } else if ((obj == CASTLE) || (loc(obj) == ROOMS)) {
    tell("\"Oh, it is a lovely piece of real estate, ");
    if (per == FRIEND) {
      tell("isn't it");
    } else {
      tell("what");
    }
    tell(C(63));
    if (per == DOCTOR || per == PAINTER || per == DEALER) {
      tell(" Almost a shame to admit riffraff on weekends.");
    }
    tell("\"\n");
    return true;
  } else if (loc(obj) == per) {
    tell("\"I have it right here, ");
    if (await TITLE_NAME()) {
      tell(C(46));
    }
    tell("\"\n");
    return true;
  } else {
    return false;
  }
}

async function SHOWING_CLUE$(obj) {
  if (obj == CLUE_1 || obj == CLUE_2) {
    return true;
  } else if (obj == CLUE_3 || obj == CLUE_4) {
    return true;
  } else if ((obj == MAGAZINE) && (g.VARIATION == PAINTER_C)) {
    return true;
  } else {
    return false;
  }
}

async function TREASURE_FOUND$(obj, per) {
  let x = 0;
  if ((obj == g.TREASURE) || ((obj == INKWELL) && (loc(MOONMIST) == INKWELL))) {
    clearFlag(obj, SECRETBIT);
    tell("\"That must be the ", D(ARTIFACT), "!");
    x = await TELL_STOP_SEARCHING$(per);
    tell("\"\n");
    if ((loc(per = FRIEND) == g.HERE) || (loc(per = LORD) == g.HERE)) {
      if (!(per == g.CONFESSED)) {
        putProp(per, P.LINE, 0);
        await THIS_IS_IT(per);
        tell("\"That's super!\" adds ", D(per), ". \"We can't thank you enough!");
        if (x == 0) {
          x = await TELL_STOP_SEARCHING$(per);
        }
        tell("\"\n");
      }
    }
    if ((loc(g.SEARCHER) == g.HERE) && (x == 0) && (await TELL_STOP_SEARCHING$(g.SEARCHER, true, true))) {
      tell("\" says ", D(g.SEARCHER), ".\n");
    }
    if (g.TREASURE_FOUND == 0) {
      await CONGRATS(ARTIFACT);
    }
    return true;
  } else {
    return false;
  }
}

async function TELL_STOP_SEARCHING$(per, comma = false, nosp = false) {
  let obj = 0;
  if ((per == g.SEARCHER) && eq(get(obj = get(g.GOAL_TABLES, getProp(per, P.CHARACTER)), GOAL_FUNCTION), X_SEARCHES.id)) {
    put(obj, GOAL_FUNCTION, NULL_F.id);
    if (nosp == 0) {
      tell(C(32));
    } else {
      tell(C(34));
    }
    tell("Then that's the end of my searching");
    if (!(comma == 0)) {
      tell(C(44));
    } else {
      tell(C(46));
    }
    if (!(obj = await ZMEMQ(g.HERE, g.CHAR_ROOM_TABLE)) || !(per == get(g.CHARACTER_TABLE, obj - 1))) {
      await ESTABLISH_GOAL(per, SITTING_ROOM);
    }
    return true;
  } else {
    return false;
  }
}

async function GOOD_SHOW(per, obj) {
  if (per == GHOST_NEW || per == g.CONFESSED) {
    return false;
  }
  tell(C(34));
  if (g.VARIATION == getProp(per, P.CHARACTER)) {
    tell("How nice");
  } else if (per == FRIEND) {
    tell("That's keen");
  } else if (random(2) == 1) {
    tell("Well done");
  } else {
    tell("Good show");
  }
  tell("! You found ");
  await PRINTA(obj);
  tell(C(33));
  if (obj == g.TREASURE) {
    await TELL_STOP_SEARCHING$(per, true);
  }
  tell("\" says ", D(per), ".\n");
  return true;
}

async function COMMON_DESC(per) {
  tell("He's a ");
  if (per == DOCTOR) {
    tell("middle-sized man in his fifties");
    if (loc(MUSTACHE) == DOCTOR) {
      tell(", with spectacles and a grizzled mustache");
    }
    tell(".\n");
    return true;
  }
  tell("tall");
  if (per == LORD) {
    tell(", handsome, dark-browed young man");
    if (BED_TIME > g.PRESENT_TIME) {
      tell(" in dinner jacket and black tie");
    }
  } else if (per == OFFICER) {
    tell(" blond");
    if (BED_TIME > g.PRESENT_TIME) {
      tell(", sporting a white dinner jacket and scarlet cummerbund. He moves with the elegant swagger of a Guards officer and young-man-about-Mayfair, both of which he is");
    }
  } else if (per == DEALER) {
    tell(", foppish art and antiques dealer");
    if (!(hasFlag(per, MUNGBIT))) {
      tell(". Despite his languid manner, you're aware of his penetrating glance. If you were buying a used car from this man, you'd want to check it out carefully");
    }
  }
  tell(".\n");
  return true;
}

async function COMMON_OTHER(per) {
  let x = false, n_ = 0;
  if (isVerb(V.ASK)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    if ((per == DOCTOR) || (per == LORD || per == OFFICER || per == DEALER)) {
      await COMMON_DESC(per);
    } else if (!(per == GHOST_NEW)) {
      tell(S(getProp(per, P.TEXT)), "\n");
    }
    if ((loc(per) == g.HERE) && (n_ = first(per)) && !(hasFlag(n_, NDESCBIT))) {
      if (await CARRY_CHECK(per)) {
        x = true;
      }
    }
    if (hasFlag(per, MUNGBIT)) {
      if (!(x == 0)) {
        tell("And");
      }
      (await HE_SHE_IT(per, !x, "is"));
      printC(32);
      tell(S(get(g.LDESC_STRINGS, getProp(per, P.LDESC))), ".\n");
    }
    if (per == DEALER) {
      if (eq(loc(LORD), g.HERE, PSEUDO_OBJECT) && eq(getProp(DEALER, P.LDESC), 2) && (getProp(LORD, P.LINE) == 0)) {
        tell("\"Montague began appraising the art works in the castle for Uncle Lionel before he died,\" explains ", D(LORD), ". \"I've asked him to continue and make up a catalog.\"\n");
      }
    } else if (per == PAINTER) {
      if (eq(loc(FRIEND), g.HERE, PSEUDO_OBJECT)) {
        x = FRIEND;
      } else {
        x = await FIND_FLAG_HERE(PERSONBIT, PLAYER, PAINTER);
      }
      if (!(x == 0) && eq(loc(PAINTER), DRAWING_ROOM)) {
        tell("\"Vivien painted that portrait of ", D(LOVER), " Hallam, the girl who drowned in the castle well,\" says ", D(x), ". She gestures to a framed picture hanging by the ", D(FIREPLACE), ".\n");
      }
    }
    return true;
  } else if ((g.PRSO == per) && isVerb(V.SHOW)) {
    await PERFORM(V.ASK_ABOUT, g.PRSO, g.PRSI);
    return true;
  } else {
    return false;
  }
}

async function UNSNOOZE(per, no_tell$ = false) {
  let rm = 0, gt = 0, c_ = getProp(per, P.LDESC);
  if (c_ == 14) {
    await FIX_MUSTACHE(per);
    c_ = getProp(per, P.CHARACTER);
    gt = get(g.GOAL_TABLES, c_);
    put(gt, ATTENTION, get(gt, ATTENTION_SPAN));
    put(gt, GOAL_ENABLE, 0);
    put(gt, GOAL_FUNCTION, X_RETIRES.id);
    put(gt, GOAL_S, true);
    rm = get(g.CHAR_ROOM_TABLE, 1 + c_);
    if (!(loc(per) == rm)) {
      await ESTABLISH_GOAL(per, rm);
    }
    if (g.VARIATION == c_) {
      putProp(per, P.LDESC, 4);
    } else {
      putProp(per, P.LDESC, 25);
    }
    clearFlag(per, MUNGBIT);
    rm = await META_LOC(per);
    if ((loc(per) == g.HERE) && (no_tell$ == 0)) {
      await HE_SHE_IT(per, true);
      tell(" wakes up first. ");
      if (!(hasFlag(rm, ONBIT))) {
        await HE_SHE_IT(per, true);
        tell(" turns on the light. ");
      }
    }
    setFlag(rm, ONBIT);
    return true;
  } else if ((c_ == 19) && (get(g.SHOT, getProp(per, P.CHARACTER)) == 0)) {
    await FIX_MUSTACHE(per);
    await QUEUE(I_COME_TO.id, 0);
    await I_COME_TO();
    return true;
  } else {
    return false;
  }
}

async function FIX_MUSTACHE(per) {
  if ((per == DOCTOR) && (g.VARIATION == DOCTOR_C)) {
    clearFlag(MUSTACHE, TAKEBIT);
    return setFlag(MUSTACHE, TRYTAKEBIT);
  } else {
    return false;
  }
}

