async function DRIVING$() {
  if (!(g.P_PRSA_WORD == 0) && !(g.P_PRSA_WORD == W.DRIVE || g.P_PRSA_WORD == W.ENTER || g.P_PRSA_WORD == W.STEER)) {
    return false;
  } else if (isVerb(V.CLIMB_UP, V.THROUGH, V.WALK_TO)) {
    if (isVerb(V.THROUGH) && (g.PRSO == CAR)) {
      if (!(g.PRSI == 0)) {
        if (!(g.HERE == (await META_LOC(g.PRSI)))) {
          g.PRSO = g.PRSI;
          return true;
        } else {
          return false;
        }
      } else {
        g.PRSO = FRONT_GATE;
        return true;
      }
    } else if (!(g.HERE == (await META_LOC(g.PRSO)))) {
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.LEAVE)) {
    if (!(g.PRSO == ROOMS || g.PRSO == CAR)) {
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.WALK)) {
    if (!(g.P_PRSA_WORD == 0) || !(g.PRSO == P.OUT)) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CAR_F(arg = false) {
  let s_ = 0;
  s_ = g.HERE;
  if (arg == M_BEG) {
    if (await DRIVING$()) {
      if (g.PRSO == FRONT_GATE) {
        if (isVerb(V.THROUGH)) {
          if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else if (s_ == DRIVEWAY) {
            await PERFORM(V.WALK_TO, COURTYARD);
            return true;
          } else {
            await PERFORM(V.WALK_TO, DRIVEWAY);
            return true;
          }
        } else {
          return await WALK_WITHIN_ROOM();
        }
      } else if (s_ == DRIVEWAY) {
        if (isVerb(V.CLIMB_UP, V.THROUGH, V.WALK_TO)) {
          if (DRIVEWAY == (await META_LOC(g.PRSO))) {
            return await WALK_WITHIN_ROOM();
          } else if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_COURTYARD();
          }
        } else if (isVerb(V.LEAVE)) {
          if (g.PRSO == COURTYARD) {
            return await HAR_HAR();
          } else if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_COURTYARD();
          }
        } else if ((g.PRSO == P.IN || g.PRSO == P.SOUTH) || ((g.PRSO == INTDIR) && (await ADJ_USED$(W.SOUTH)))) {
          if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_COURTYARD();
          }
        } else {
          g.CLOCK_WAIT = true;
          tell(S(g.CASTLE_IS_SOUTH));
          return true;
        }
      } else {
        if (isVerb(V.CLIMB_UP, V.THROUGH, V.WALK_TO)) {
          if (COURTYARD == (await META_LOC(g.PRSO))) {
            return await WALK_WITHIN_ROOM();
          } else if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_DRIVEWAY();
          }
        } else if (isVerb(V.LEAVE)) {
          if (g.PRSO == DRIVEWAY) {
            return await HAR_HAR();
          } else if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_DRIVEWAY();
          }
        } else if ((g.PRSO == P.NORTH) || ((g.PRSO == INTDIR) && (await ADJ_USED$(W.NORTH)))) {
          if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_DRIVEWAY();
          }
        } else if (g.PRSO == P.OUT) {
          if (g.P_PRSA_WORD == false || g.P_PRSA_WORD == W.GO) {
            return false;
          } else if (!(hasFlag(FRONT_GATE, OPENBIT))) {
            return (await TOO_BAD_BUT(FRONT_GATE, "closed"));
          } else {
            return await CAR_TO_DRIVEWAY();
          }
        } else {
          return (await YOU_CANT("drive"));
        }
      }
    } else if (isVerb(V.WALK) && (g.PRSO == P.OUT)) {
      move(g.WINNER, g.HERE);
      return await OWN_FEET();
    } else if (isVerb(V.FOLLOW, V.STAND, V.WALK) || (isVerb(V.LEAVE, V.THROUGH, V.WALK_TO) && !(g.PRSO == 0) && !(g.PRSO == LUGGAGE || g.PRSO == ROOMS || g.PRSO == CAR))) {
      (await FIRST_YOU("leave", CAR));
      move(g.WINNER, g.HERE);
      if (isVerb(V.STAND)) {
        return true;
      } else {
        return false;
      }
    } else if (g.PRSO == ROOMS) {
      if (isVerb(V.STOP)) {
        await PERFORM(g.PRSA, CAR);
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (arg == M_LOOK) {
    if (eq(loc(g.WINNER), CAR)) {
      tell("You are sitting in your new little ", D(CAR), ".\n");
    }
    return true;
  } else if (arg) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await TELL_ABOUT_CAR();
    return true;
  } else if (isVerb(V.CLIMB_ON, V.CLOSE, V.OPEN, V.LAMP_OFF, V.LAMP_ON, V.LOCK, V.UNLOCK)) {
    return (await NO_NEED("do that to"));
  } else {
    return false;
  }
}

