async function FRONT_GATE_F() {
  if (isVerb(V.KNOCK)) {
    tell("Apparently no one hears you.\n");
    return true;
  } else if (isVerb(V.MUNG, V.SHAKE, V.UNLOCK)) {
    tell("Except for your rattling the gate, the silence remains unbroken.\n");
    return true;
  } else if (isVerb(V.BOARD, V.CLIMB_ON, V.LEAP)) {
    tell(S(g.TOO_SLIPPERY));
    return true;
  } else if (isVerb(V.WALK_TO) && !(g.HERE == DRIVEWAY || g.HERE == COURTYARD)) {
    await PERFORM(g.PRSA, COURTYARD);
    return true;
  } else if (isVerb(V.OPEN)) {
    if (hasFlag(FRONT_GATE, LOCKED)) {
      tell("It seems to be locked.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.SEARCH, V.SEARCH_FOR)) {
    if (g.HERE == DRIVEWAY) {
      await TELL_ABOUT_DRAGON();
      return true;
    } else {
      return false;
    }
  } else if (loc(VOICE) == g.HERE) {
    return await VOICE_F();
  } else {
    return false;
  }
}

async function COURTYARD_F(rarg = 0) {
  if (rarg == M_ENTER) {
    if (loc(FRIEND) == LIMBO) {
      move(FRIEND, COURTYARD);
    }
    if (!(g.DRAGON_EYE_COLOR == 0)) {
      g.DRAGON_EYE_COLOR = 0;
    }
    if (!(hasFlag(FRONT_GATE, LOCKED))) {
      clearFlag(FRONT_GATE, OPENBIT);
      setFlag(FRONT_GATE, LOCKED);
      tell("The ", D(FRONT_GATE), " closes and locks behind you.\n");
      return true;
    } else {
      return false;
    }
  } else if (rarg == M_LOOK) {
    if (!(hasFlag(g.HERE, TOUCHBIT))) {
      setFlag(g.HERE, TOUCHBIT);
      tell("As flood lights blaze on, you look around. ");
    }
    await TELL_LIKE_BROCHURE();
    tell(S(g.DARK_TURRETS));
    return true;
  } else if (rarg == M_FLASH) {
    if ((loc(FRIEND) == COURTYARD) && !(hasFlag(FRIEND, TOUCHBIT)) && (g.CLOCK_WAIT == 0)) {
      setFlag(FRIEND, TOUCHBIT);
      clearFlag(FRIEND, NDESCBIT);
      g.FOLLOWER = FRIEND;
      g.QCONTEXT = FRIEND;
      await QUEUE(I_FRIEND_GREETS.id, 0);
      await QUEUE(I_TOUR.id, 7);
      await ESTABLISH_GOAL(BUTLER, COURTYARD);
      clearFlag(FRONT_DOOR, LOCKED);
      g.QCONTEXT = FRIEND;
      await THIS_IS_IT(FRIEND);
      putProp(FRIEND, P.LDESC, 12);
      g.AWAITING_REPLY = FRIEND_C;
      await QUEUE(I_REPLY.id, g.CLOCKER_RUNNING);
      tell("\nSomeone comes running out of the wing to greet you. ", S(getProp(FRIEND, P.TEXT)), " You recognize her as your friend, ", D(FRIEND), " Lynd.\n\"");
      await PRINT_NAME(g.FIRST_NAME);
      tell("!\" she cries with outflung arms. \"You sweet thing, to answer my letter in person this way! And all the people I wrote about are here tonight for Lionel's memorial birthday dinner!\"\nAfter a warm hug, she asks anxiously, \"", S(get(g.QUESTIONS, g.AWAITING_REPLY)), "\"\n");
      return M_FATAL;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

