async function POPULATION(rm, not1 = false, not2 = false) {
  let cnt = 0, obj = 0;
  obj = first(rm);
  if (obj == 0) {
    return false;
  }
  for (;;) {
    if (hasFlag(obj, PERSONBIT) && !(hasFlag(obj, INVISIBLE)) && ((not1 == 0) || !(obj == not1)) && ((not2 == 0) || !(obj == not2))) {
      cnt = cnt + 1;
    } else if (hasFlag(obj, CONTBIT)) {
      cnt = cnt + (await POPULATION(obj, not1, not2));
    }
    obj = next(obj);
    if (obj == 0) {
      return cnt;
    }
  }
}

