async function TELL_AS_WELL_AS(cont, str, obj = false, x = false) {
  if (hasFlag(cont, SURFACEBIT)) {
    tell(C(79));
  } else {
    setFlag(cont, OPENBIT);
    tell(C(73));
  }
  tell(C(110));
  await PRINTT(cont);
  tell(" you see");
  if (await FIND_FLAG_NOT(cont, NDESCBIT)) {
    x = true;
  } else {
    tell(" only");
  }
  if (!(obj == 0)) {
    await PRINTT(obj);
  } else {
    tell(S(str));
  }
  if (!(x == 0)) {
    tell(", as well as");
    await PRINT_CONTENTS(cont);
  }
  tell(".\n");
  return true;
}

