async function SECRET_CHECK(rarg = false) {
  let obj = false, per = false, rm = 0, gt = 0;
  if (g.DISCOVERED_HERE == g.HERE) {
    per = get(g.CHARACTER_TABLE, (await ZMEMQ(g.HERE, g.CHAR_ROOM_TABLE)) - 1);
    if (hasFlag(per, MUNGBIT) || (per == g.CONFESSED) || !(eq(await META_LOC(per), g.HERE))) {
      per = false;
    }
  }
  if (rarg == M_BEG) {
    if (isVerb(V.WALK) || (isVerb(V.WALK_TO, V.FOLLOW, V.THROUGH) && !(g.HERE == (await META_LOC(g.PRSO))))) {
      return false;
    } else if (!(per == 0) && (!(getProp(per, P.LINE) == 0) || isVerb(V.SEARCH, V.SEARCH_FOR)) && !(per == g.PRSO || per == g.PRSI) && !(await FREE_VERB$())) {
      await START_SENTENCE(per);
      tell(" prevents");
      await HIM_HER_IT(g.WINNER, false, true);
      tell(" action!\n");
      return true;
    } else {
      return false;
    }
  } else if ((rarg == M_EXIT) && !(per == 0)) {
    rm = await GENERIC_CLOSET(0);
    gt = get(g.GOAL_TABLES, getProp(per, P.CHARACTER));
    if (isVerb(V.WALK)) {
      obj = g.PRSO;
    } else if (isVerb(V.WALK_TO, V.FOLLOW, V.THROUGH)) {
      obj = await META_LOC(g.PRSO);
      if ((obj == g.HERE) || ((obj == LOCAL_GLOBALS) && !(hasFlag(g.PRSO, DOORBIT)))) {
        return false;
      } else if (isVerb(V.THROUGH)) {
        if (obj == rm || obj == LOCAL_GLOBALS) {
          await ESTABLISH_GOAL(per, get(gt, GOAL_F));
          g.DISCOVERED_HERE = false;
          return false;
        }
        obj = P.OUT;
      } else {
        obj = await DIR_FROM(g.HERE, obj);
      }
    }
    if ((await DIR_EQV$(g.HERE, obj, P.OUT)) && !(getProp(per, P.LINE) == 0)) {
      await HE_SHE_IT(per, true);
      tell(" blocks");
      await HIM_HER_IT(g.WINNER, false, true);
      tell(" exit!\n");
      return true;
    }
    if (per == GHOST_NEW) {
      move(per, rm);
    }
    await ESTABLISH_GOAL(per, get(gt, GOAL_F));
    g.DISCOVERED_HERE = false;
    return false;
  } else {
    return false;
  }
}

async function OPEN_SECRET(act_, obj, dr) {
  tell("As");
  await HE_SHE_IT(g.WINNER, false, act_);
  if (act_ == 0) {
    tell(C(32));
    await VERB_PRINT();
  }
  if ((obj > 0) && (obj < 256)) {
    await PRINTT(obj);
    clearFlag(obj, SECRETBIT);
  } else {
    printS(obj);
  }
  tell(C(44));
  if (!(hasFlag(dr, TOUCHBIT))) {
    setFlag(dr, TOUCHBIT);
    await QUEUE(I_FOUND_PASSAGES.id, 1);
    if (!((act_ = await GENERIC_CLOSET(0)) == 0)) {
      put(g.FOUND_PASSAGES, PLAYER_C, act_);
    } else {
      put(g.FOUND_PASSAGES, PLAYER_C, true);
    }
    setFlag(PASSAGE, SEENBIT);
    if (obj == HISTORY_BOOK) {
      setFlag(HISTORY_BOOK, TAKEBIT);
      clearFlag(HISTORY_BOOK, TRYTAKEBIT);
      await PRINTT(BOOKCASE);
    } else {
      tell(" a section of the ");
      if (obj == WYVERN) {
        tell(D(WYVERN));
      } else {
        tell("wall");
      }
    }
  } else {
    await PRINTT(dr);
  }
  return await OPEN_CLOSE(dr, false);
}

