async function BELL_F() {
  let n_ = 0, p_ = 0, gt = 0;
  if (isVerb(V.MOVE, V.MOVE_DIR, V.PUSH, V.TURN)) {
    return (await TOO_BAD_BUT(BELL, "too heavy"));
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.LOOK_UNDER, V.SEARCH, V.SEARCH_FOR)) {
    if ((g.VARIATION == PAINTER_C) && hasFlag(SKULL, SECRETBIT)) {
      await DISCOVER(SKULL);
      return true;
    } else if ((loc(CLUE_3) == BELL) && hasFlag(CLUE_3, SECRETBIT)) {
      await DISCOVER(CLUE_3);
      return true;
    } else {
      (await TELL_AS_WELL_AS(BELL, " the clapper"));
      return true;
    }
  } else if (isVerb(V.RING)) {
    if (!(g.PLAYER_RANG_BELL$ == 0)) {
    } else if (!(loc(BUTLER) == LOCAL_GLOBALS)) {
      if (!(loc(BUTLER) == KITCHEN)) {
        await GO_TO_SOUND(KITCHEN, BUTLER);
      }
    } else if (g.LIONEL_SPEAKS_COUNTER == 0) {
      g.MASS_SAID = false;
      loop1: for (;;) {
        if (++n_ > DEB_C) {
          break loop1;
        }
        p_ = get(g.CHARACTER_TABLE, n_);
        if (!(p_ == g.CONFESSED || p_ == g.CAPTOR) && !(p_ == GHOST_NEW || p_ == g.SEARCHER)) {
          await GO_TO_SOUND(DECK, p_);
        }
      }
    }
    g.PLAYER_RANG_BELL$ = true;
    tell("Its deep booming \"gong\" can be felt in every room of the castle.");
    crlf();
    if ((g.HERE == DECK) && (p_ = await FIND_FLAG_HERE_NOT(PERSONBIT, MUNGBIT, PLAYER))) {
      tell(D(p_), " whispers, \"That's ");
      if (first(BELL)) {
        tell("not ");
      }
      tell("too loud for comfort!\"");
      crlf();
    }
    return true;
  } else {
    return false;
  }
}

async function GO_TO_SOUND(rm, p_) {
  let gt = 0, gf = 0, l = loc(p_);
  if (!(loc(p_) == rm) && !(hasFlag(p_, MUNGBIT))) {
    gt = get(g.GOAL_TABLES, getProp(p_, P.CHARACTER));
    gf = get(gt, GOAL_FUNCTION);
    if ((p_ == BUTLER) && !(gf == X_TO_BELL.id)) {
      g.BUTLER_DUTY = gf;
    }
    put(gt, GOAL_FUNCTION, X_TO_BELL.id);
    if (await IN_MOTION$(p_, true)) {
      put(gt, GOAL_QUEUED, get(gt, GOAL_F));
    } else {
      put(gt, GOAL_QUEUED, l);
    }
    if ((random(2) == 1) && ((hasFlag(rm, WEARBIT) && !(hasFlag(l, WEARBIT))) || (!(hasFlag(rm, WEARBIT)) && hasFlag(l, WEARBIT)))) {
      move(p_, JUNCTION);
    }
    return await ESTABLISH_GOAL(p_, rm);
  } else {
    return false;
  }
}

async function X_TO_BELL(garg = false) {
  let l = loc(g.GOAL_PERSON), gt = get(g.GOAL_TABLES, getProp(g.GOAL_PERSON, P.CHARACTER));
  if ((garg == G_REACHED) || (l == g.HERE)) {
    if (BED_TIME < g.PRESENT_TIME) {
      await QUEUE(I_BEDTIME.id, 15);
    }
    put(gt, ATTENTION, get(gt, ATTENTION_SPAN));
    if (g.GOAL_PERSON == BUTLER) {
      put(gt, GOAL_FUNCTION, g.BUTLER_DUTY);
    } else {
      put(gt, GOAL_FUNCTION, NULL_F.id);
    }
    putProp(g.GOAL_PERSON, P.LDESC, 4);
    if ((l == g.HERE) && (g.MASS_SAID == 0)) {
      g.MASS_SAID = true;
      await HE_SHE_IT(g.GOAL_PERSON, true);
      tell(" appears and says, \"What's all this, then?\"\n");
      return M_FATAL;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

