async function NO_VIOLENCE$(obj) {
  let p_ = 0;
  let $1;
  if (isVerb(V.ATTACK, V.KILL, V.SHOOT, V.SLAP)) {
    p_ = g.PRSO;
  } else {
    p_ = g.PRSI;
  }
  if (p_ == 0) {
    p_ = await FIND_FLAG_HERE_NOT(PERSONBIT, MUNGBIT, g.WINNER);
  }
  if (p_ == 0) {
    g.CLOCK_WAIT = true;
    tell("(You didn't say whom to use it on!)\n");
    return false;
  }
  if (!(p_ == GHOST_NEW) && (!g.VILLAIN_KNOWN$ || !(p_ == g.VILLAIN_PER))) {
    tell(S(g.NO_VIOLENCE));
    return false;
  } else if (hasFlag(p_, MUNGBIT)) {
    tell(S(g.NO_VIOLENCE));
    return false;
  } else if (!(g.VILLAIN_PER == LOVER) && !(await QUEUED$(I_SHOT.id))) {
    tell(S(g.NO_VIOLENCE));
    return false;
  } else if (!(g.LIONEL_SPEAKS_COUNTER == 0)) {
    await TELL_BAD_FORM();
    return false;
  } else {
    g.SHOOTER = false;
    await QUEUE(I_SHOT.id, 0);
    if (g.VILLAIN_PER == LOVER) {
      await GHOST_FLEES();
      return false;
    }
    setFlag(p_, MUNGBIT);
    clearFlag(p_, NDESCBIT);
    putProp(p_, P.LDESC, 19);
    put(get(g.GOAL_TABLES, getProp(p_, P.CHARACTER)), ATTENTION, 0);
    if (p_ == GHOST_NEW) {
      put(get(g.GOAL_TABLES, getProp(g.VILLAIN_PER, P.CHARACTER)), ATTENTION, 0);
    }
    if (obj == CANE || obj == WAR_CLUB || obj == MACE) {
      await QUEUE(I_COME_TO.id, 9 + random(6));
    } else {
      put(g.SHOT, getProp(p_, P.CHARACTER), true);
      if (p_ == GHOST_NEW) {
        put(g.SHOT, getProp(g.VILLAIN_PER, P.CHARACTER), true);
      }
    }
    putProp(p_, P.LINE, 3 + getProp(p_, P.LINE));
    await HE_SHE_IT(p_, true);
    if (loc(BLOWGUN) == p_) {
      setFlag(BLOWGUN, TAKEBIT);
      clearFlag(BLOWGUN, NDESCBIT);
      move(BLOWGUN, g.HERE);
      tell(" drops");
      await PRINTT(BLOWGUN);
      tell(" and");
    }
    if (obj == MACE) {
      tell(" claps both hands over");
      await HIM_HER_IT(p_, false, true);
      tell(" mouth and nose. ");
      await HIM_HER_IT(p_, true, true);
      tell(" face takes on a greenish pallor, and strangled noises issue from");
      await HIM_HER_IT(p_, false, true);
      tell(" throat");
    } else {
      tell(" looks surprised and stunned. Then");
      await HIM_HER_IT(p_, false, true);
      tell(" eyes flutter");
    }
    tell(". Next moment");
    await HE_SHE_IT(p_);
    tell(" collapses ");
    $1 = await GROUND_DESC();
    tell(S($1));
    tell("!\n");
    return p_;
  }
}

