async function DOOR_ROOM(rm, dr) {
  let p_ = 0, tbl = 0;
  for (;;) {
    if (((p_ = nextProp(rm, p_)) == 0) || (p_ < LOW_DIRECTION)) {
      return false;
    } else if ((DEXIT == propSize(tbl = getPropAddr(rm, p_))) && (dr == getb(tbl, DEXITOBJ))) {
      return getb(tbl, REXIT);
    }
  }
}

async function FIND_FLAG(rm, flag, excluded = false) {
  let o = 0;
  o = first(rm);
  for (;;) {
    if (!o) {
      return false;
    } else if (hasFlag(o, flag) && !(hasFlag(o, INVISIBLE)) && !(o == excluded)) {
      return o;
    } else {
      o = next(o);
    }
  }
}

async function FIND_FLAG_NOT(rm, flag) {
  let o = 0;
  o = first(rm);
  for (;;) {
    if (!o) {
      return false;
    } else if (!(hasFlag(o, flag)) && !(hasFlag(o, INVISIBLE))) {
      return o;
    } else {
      o = next(o);
    }
  }
}

async function FIND_FLAG_LG(rm, flag, flag2 = 0) {
  let tbl = 0, o = 0, cnt = 0, size = 0;
  if (tbl = getPropAddr(rm, P.GLOBAL)) {
    size = propSize(tbl) - 1;
    for (;;) {
      o = getb(tbl, cnt);
      if (hasFlag(o, flag) && !(hasFlag(o, INVISIBLE)) && ((flag2 == 0) || hasFlag(o, flag2))) {
        return o;
      } else if (++cnt > size) {
        return false;
      }
    }
  } else {
    return false;
  }
}

async function FIND_FLAG_HERE(flag, not1 = false, not2 = false) {
  let o = 0;
  o = first(g.HERE);
  for (;;) {
    if (!o) {
      return false;
    } else if (hasFlag(o, flag) && !(hasFlag(o, INVISIBLE)) && !(o == not1 || o == not2)) {
      return o;
    } else {
      o = next(o);
    }
  }
}

async function FIND_FLAG_HERE_NOT(flag, nflag, not2 = false) {
  let o = 0;
  o = first(g.HERE);
  for (;;) {
    if (!o) {
      return false;
    } else if (hasFlag(o, flag) && !(hasFlag(o, nflag)) && !(hasFlag(o, INVISIBLE)) && !(o == not2)) {
      return o;
    } else {
      o = next(o);
    }
  }
}

async function LEVER_F() {
  let x = false;
  if (hasFlag(g.HERE, SECRETBIT)) {
    x = await FIND_FLAG_LG(g.HERE, DOORBIT);
  } else if (g.HERE == DUNGEON || g.HERE == LOVER_PATH) {
    x = PRIEST_DOOR;
  }
  if (x == 0) {
    await NOT_HERE(LEVER);
    return true;
  } else if (isVerb(V.MOVE, V.MOVE_DIR, V.PUSH, V.RUB, V.TAKE, V.TURN)) {
    setFlag(x, TOUCHBIT);
    return await OPEN_CLOSE(x);
  } else if (isVerb(V.OPEN)) {
    setFlag(x, TOUCHBIT);
    (await OKAY(x, "open"));
    return true;
  } else if (isVerb(V.CLOSE)) {
    setFlag(x, TOUCHBIT);
    (await OKAY(x, "closed"));
    return true;
  } else {
    return false;
  }
}

async function OPEN_CLOSE(dr, say_name = true, x = 0) {
  if (say_name) {
    await START_SENTENCE(dr);
  }
  tell(" creaks ");
  if (hasFlag(dr, OPENBIT)) {
    clearFlag(dr, OPENBIT);
    await THIS_IS_IT(dr);
    tell("closed.\n");
    await REMOVE_CAREFULLY();
    return true;
  } else if (x = await DOOR_ROOM(g.HERE, dr)) {
    setFlag(dr, OPENBIT);
    await THIS_IS_IT(x);
    tell("open, revealing");
    if (hasFlag(g.HERE, SECRETBIT)) {
      await PRINTT(x);
    } else if (g.HERE == LOVER_PATH) {
      await PRINTT(DUNGEON);
    } else {
      tell(" a ", D(PASSAGE));
    }
    setFlag(dr, SEENBIT);
    setFlag(x, SEENBIT);
    tell("!\n");
    return true;
  } else {
    return false;
  }
}

