async function CORRIDOR_LOOK(itm = false) {
  let c_ = 0, z = 0, cor = 0, val = 0, found = false;
  if (!((c_ = getProp(g.HERE, P.CORRIDOR)) == 0)) {
    loop1: for (;;) {
      if (!((z = c_ - 4) < 0)) {
        cor = g.COR_4;
      } else if (!((z = c_ - 2) < 0)) {
        cor = g.COR_2;
      } else if (!((z = c_ - 1) < 0)) {
        cor = g.COR_1;
      } else {
        break loop1;
      }
      val = await CORRIDOR_CHECK(cor, itm);
      if (!found) {
        found = val;
      }
      c_ = z;
    }
    return found;
  } else {
    return false;
  }
}

async function CORRIDOR_CHECK(cor, itm) {
  let cnt = 1, past = 0, found = false, rm = 0, obj = 0;
  loop1: for (;;) {
    cnt = cnt + 1;
    rm = get(cor, cnt);
    if (rm == 0) {
      return false;
    } else if (rm == itm) {
      return get(cor, past);
    } else if ((itm == ROOMS) && (await THIS_IT$(rm))) {
      return rm;
    } else if (((await LIT$(rm)) == 0) && !(itm == ROOMS)) {
      continue loop1;
    } else if (rm == g.HERE) {
      past = 1;
    } else if (obj = first(rm)) {
      loop2: for (;;) {
        if (itm) {
          if (obj == itm) {
            found = get(cor, past);
            break loop2;
          }
        } else if (hasFlag(obj, PERSONBIT) && !(await IN_MOTION$(obj, true))) {
          tell(D(obj), " is in");
          await PRINTT(rm);
          tell(".\n");
        }
        obj = next(obj);
        if (!obj) {
          break loop2;
        }
      }
      if (found) {
        return found;
      }
    }
  }
}

