async function GET_COLOR() {
  let num = 0, n_ = 0, wd = 0, sum = 0, x = 0;
  putb(g.P_INBUF, 0, 30);
  loop1: for (;;) {
    tell(C(62));
    await read(g.P_INBUF, g.P_LEXV);
    num = getb(g.P_LEXV, P_LEXWORDS);
    if (num == 0) {
      tell(C(34), S(g.BEG_PARDON), "\" ");
      continue loop1;
    }
    n_ = P_LEXSTART;
    loop2: for (;;) {
      wd = get(g.P_LEXV, n_);
      if (x = await ZMEMQ(wd, g.COLOR_WORDS)) {
        g.VARIATION = x;
        break loop2;
      } else if (--num < 1) {
        break loop2;
      } else {
        n_ = n_ + P_LEXELEN;
      }
    }
    wd = P_LEXSTART + (P_LEXELEN * (getb(g.P_LEXV, P_LEXWORDS) - 1));
    if (eq(get(g.P_LEXV, wd), W.PERIOD, W.$, W.$)) {
      wd = wd - P_LEXELEN;
    }
    n_ = 2 * (wd + 1);
    wd = (-1) + (getb(g.P_LEXV, n_) + getb(g.P_LEXV, 1 + n_));
    await NON_BLANK_STUFF(g.FAVE_COLOR, g.P_INBUF + 1, wd);
    tell("\"Did you say ", D(YOUR_COLOR), " is ");
    await PRINT_COLOR(true);
    tell("?\"");
    if (await YES$()) {
      if (g.VARIATION == 0) {
        sum = getb(g.P_INBUF, getb(g.P_LEXV, 3 + (2 * P_LEXSTART)));
        if (x = await ZMEMQ(sum, g.COLOR_LETTERS)) {
          g.VARIATION = x;
        } else if (sum == 112) {
          g.VARIATION = PAINTER_C;
        } else {
          g.VARIATION = 1 + mod(sum, MAX_VARS);
        }
        g.COLOR_FORCED = get(g.COLOR_WORDS, g.VARIATION);
      }
      await DO_VARIATION();
      putb(g.P_INBUF, 0, 80);
      return true;
    } else {
      tell("\"What, then?\"\n");
      g.VARIATION = 0;
    }
  }
}

